Box(modifier = Modifier.fillMaxSize()) {
    val isHttpSource = viewModel.getSource() is HttpSource
    var showTtsDialog by remember { mutableStateOf(false) }
    // Полная настройка «как читать баблы» (OCR): отдельная кнопка в
