      *  - slow — медленно (~15% экрана за шаг);
      *  - normal — обычно (~35% экрана за шаг, с перекрытием кадра);
      *  - fast — быстрее (~55%);
      *  - max — максимально (~80%).
      */
     fun autoReadWebtoonSpeed() = preferenceStore.getString("pref_autoread_webtoon_speed", "normal")

     // ---- Веб: сохранение как локальная глава ----
     /** Сохранять веб-страницы как локальные главы с изоляцией по сайту */
     fun webSavePerSiteFolder() = preferenceStore.getBoolean("pref_web_per_site_folder", true)

     // ---- История сканирования (персистент) ----
     /** Хранить историю сканирования между перезапусками */
     fun persistOcrHistory() = preferenceStore.getBoolean("pref_persist_ocr_history", true)

     // ---- AI-чат продвинутый ----
     /** Лимит истории чата (сообщений) — чтобы не тратить 50к токенов */
     fun aiHistoryLimit() = preferenceStore.getInt("pref_ai_history_limit", 12)

     /** Лимит токенов на один ответ (reasoning + content) */
     fun aiTokenBudget() = preferenceStore.getInt("pref_ai_token_budget", 4000)

     /** Показывать что доступно/невозможно (availability report) */
     fun aiShowAvailability() = preferenceStore.getBoolean("pref_ai_show_availability", true)

     // Local Model Management (модели НЕ входят в APK — по умолчанию не установлены,
     // из коробки работают только онлайн-движки)
     fun isMangaOcrDownloaded() = preferenceStore.getBoolean("pref_model_manga_ocr_downloaded", false)
     fun isFastOcrDownloaded() = preferenceStore.getBoolean("pref_model_fast_ocr_downloaded", false)
     fun isPanelDetectorDownloaded() = preferenceStore.getBoolean("pref_model_panel_detector_downloaded", false)

     // ---- STT для игр (речь → текст → русские голоса, реал-тайм) ----
     /** Слушать микрофон и гнать речь в текст (системный SpeechRecognizer). */
     fun sttEnabled() = preferenceStore.getBoolean("pref_stt_enabled", false)

     /** Язык речи в игре (BCP-47): игры обычно английские. */
     fun sttSourceLang() = preferenceStore.getString("pref_stt_source_lang", "en-US")

     /** Переводить распознанное в русский перед озвучкой. */
     fun sttTranslate() = preferenceStore.getBoolean("pref_stt_translate", true)

     /** Пол голоса для игровых реплик: auto/female/male/narrator. */
     fun gameVoiceGender() = preferenceStore.getString("pref_game_voice_gender", "auto")

     // ---- Области поверх других приложений (игры/АПК) ----
     /**
      * Режим области: auto — весь экран; manual — задать вручную;
      * fixed — зафиксированная область (реплики игр).
      */
     fun overlayRegionMode() = preferenceStore.getString("pref_overlay_region_mode", "auto")

     /** Зафиксированная область «l,t,r,b» в долях экрана 0..1. */
     fun overlayFixedRegion() = preferenceStore.getString("pref_overlay_fixed_region", "")

     /** Показывать рамку зафиксированной области поверх приложений. */
     fun overlayShowFrame() = preferenceStore.getBoolean("pref_overlay_show_frame", false)

     /** Самому следить за буфером обмена и озвучивать новое. */
     fun overlayWatchClipboard() = preferenceStore.getBoolean("pref_overlay_watch_clipboard", false)

     // ---- Озвучка книг (свои настройки, отдельно от читалки манги) ----
     fun bookSpeechRate() = preferenceStore.getFloat("pref_book_speech_rate", 1.0f)
     fun bookSpeechPitch() = preferenceStore.getFloat("pref_book_speech_pitch", 1.0f)

     /** Движок TTS для книг: "system" или "edge". */
     fun bookTtsEngine() = preferenceStore.getString("pref_book_tts_engine", "system")

     /** Спецификация голоса: для системного "пакет::имя", для Edge — shortName. */
     fun bookVoiceSpec() = preferenceStore.getString("pref_book_voice_spec", "")

     /** Отображаемое имя голоса для UI. */
     fun bookVoiceLabel() = preferenceStore.getString("pref_book_voice_label", "")

     /** Имя TTS-голоса для книг, "" = голос по умолчанию. (legacy) */
     fun bookVoiceName() = preferenceStore.getString("pref_book_voice_name", "")

     /** Голоса по ролям: нарратив своим голосом, реплики персонажей — отдельными. */
     fun bookRoleVoices() = preferenceStore.getBoolean("pref_book_role_voices", true)

     /** Распознавать сканированные страницы (изображения PDF/EPUB) автоматически. */
     fun bookPageOcr() = preferenceStore.getBoolean("pref_book_page_ocr", true)

     /** Фоновая музыка для погружения при чтении. */
     fun bookMusicEnabled() = preferenceStore.getBoolean("pref_book_music_enabled", false)

     /** Громкость фоновой музыки (0..1). */
     fun bookMusicVolume() = preferenceStore.getFloat("pref_book_music_volume", 0.15f)

     /** Читалка во весь экран (прятать панели и системные бары). */
     fun bookFullscreen() = preferenceStore.getBoolean("pref_book_fullscreen", false)

     // ---- Скриншоты авточтения ----

     /**
      * Автоматически делать скриншот текущего кадра при каждом шаге
      * авточтения. Скриншот сохраняется в буфер и показывается на вкладке
      * «Скриншоты» с текстовым оверлеем.
      */
     fun autoScreenshotEnabled() = preferenceStore.getBoolean("pref_auto_screenshot", true)

     /**
      * Показывать индикатор в правом верхнем углу читалки при каждом
      * захвате скриншота (пульсирующая точка + количество регионов).
      */
     fun screenshotIndicatorEnabled() = preferenceStore.getBoolean("pref_screenshot_indicator", true)

     /**
      * Максимальное количество скриншотов в буфере (10..200).
      * Старые скриншоты удаляются при достижении лимита.
      */
     fun screenshotBufferSize() = preferenceStore.getInt("pref_screenshot_buffer_size", 50)

     /**
      * Сохранять ли распознанный текст на скриншоте (оверлей в галерее).
      * Выключено = только изображение без текстовых рамок.
      */
     fun screenshotShowTextOverlay() = preferenceStore.getBoolean("pref_screenshot_text_overlay", true)
 }

