                val stored = BookKnowledge.learn(
                    context = context,
                    mangaId = manga,
                    kind = kind.ifBlank { BookLearning.KIND_FACT },
                    text = fetched,
                    source = url,
                    author = BookLearning.AUTHOR_WEB,
