                ToolResult(
                    name = "book_learn",
                    output = if (stored > 0) {
                        "Источник прочитан и сохранён: $url (${stored} правил). " +
                            "Теперь выведи из него конкретные правила книги и зафиксируй их " +
                            "вызовами book_learn с kind (reading_order, region, bubble, " +
                            "transcription, voice) — без них авточтение ведёт себя по общему пресету."
