/**
 * Маскирует грубую лексику, сохраняя длину слова. Регистр и границы слова
 * учитываются, чтобы не порезать обычные слова («сук» внутри «сюжет»).
 */
fun maskCensored(text: String, words: List<String> = CENSOR_WORDS): String {
    if (text.isEmpty() || words.isEmpty()) return text
    val pattern = Regex(
        words.joinToString("|") { Regex.escape(it) },
        RegexOption.IGNORE_CASE,
    )
    return pattern.replace(text) { match ->
        val word = match.value
        // Первая буква остаётся, остальное — звёзздочки: так видно, что
        // слово было, но текст можно читать вслух.
        if (word.length <= 2) "*".repeat(word.length) else word.take(1) + "*".repeat(word.length - 1)
    }
}

/** Есть ли в тексте то, что нужно замаскировать. */
fun hasCensoredWords(text: String, words: List<String> = CENSOR_WORDS): Boolean =
    text.isNotEmpty() && words.any { text.contains(it, ignoreCase = true) }

