import java.util.regex.*;
public class MaskCheck3 {
  static String[] W = {"блядь","ебан","ебать","ебану","хуй","хуе","хуя","пизд","мудак","сука","гандон","дрочи","залуп"};
  static String mask(String text) {
    StringBuilder re = new StringBuilder();
    for (int i=0;i<W.length;i++){ if(i>0) re.append("|"); re.append(Pattern.quote(W[i])); }
    Matcher m = Pattern.compile("(?iu)" + re).matcher(text);
    StringBuffer sb = new StringBuffer();
    while (m.find()) {
      String w = m.group();
      m.appendReplacement(sb, Matcher.quoteReplacement(
        w.length() <= 2 ? "*".repeat(w.length()) : w.substring(0,1) + "*".repeat(w.length()-1)));
    }
    m.appendTail(sb);
    return sb.toString();
  }
  public static void main(String[] a) {
    for (String s : new String[]{"это блядь","БЛЯДЬ","сюжет и сюжетный","хуже","ебар","банан","дрочись","хуйня"})
      System.out.println(s + " -> [" + mask(s) + "] len=" + mask(s).length());
  }
}
