import eu.kanade.tachiyomi.data.ai.BookChatProfile

fun main() {
    val p = BookChatProfile
    check(p.maskCensored("это блядь") == "это б****") { "1: " + p.maskCensored("это блядь") }
    check(p.maskCensored("БЛЯДЬ") == "Б****") { "2: " + p.maskCensored("БЛЯДЬ") }
    check(p.hasCensoredWords("БЛЯДЬ")) { "3" }
    check(!p.hasCensoredWords("сюжет")) { "4" }
    check(p.maskCensored("хуже") == "хуже") { "5" }
    check(p.maskCensored("") == "") { "6" }
    check(p.maskCensored("дрочись").length == "дрочись".length) { "7" }
    check(p.modeTitle(p.MODE_ROLEPLAY) == "Отыгрыш") { "8" }
    check(p.modeTitle("x") == "Чат") { "9" }
    val chat = p.render(p.MODE_CHAT, false, false, "Тетрадь смерти")
    check(chat.contains("деловой") && chat.contains("18+") && chat.contains("несовершеннолетними")) { "10" }
    val rp = p.render(p.MODE_ROLEPLAY, false, true, "Тетрадь смерти")
    check(rp.contains("отыгрываешь") && rp.contains("Тетрадь смерти") && rp.contains("Знания книги")) { "11" }
    val mature = p.render(p.MODE_CHAT, true, false)
    check(mature.contains("помечена 18+")) { "12" }
    check(p.render(p.MODE_CHAT, false, false).contains("не помечена 18+")) { "13" }
    println("BookChatProfile OK")
}
EOF
