fun seriesKey(title: String): String {
    val base = title
        .replace(Regex("(?iu)\\b(том|vol|volume|часть|part|книга|book)\\s*[\\d.]+"), " ")
        .replace(Regex("[^\\p{L}\\p{N}]+"), " ")
        .trim()
        .lowercase()
    return base.ifBlank { "серия" }.take(60)
}
fun main() {
    val cases = listOf(
        "Падший лисёнок" to "Падший лисёнок Том 2",
        "Падший лисёнок — часть 3" to "Падший лисёнок, часть 3",
        "Solo Leveling vol 3" to "Solo Leveling, Vol. 4",
        "Тетрадь Смерти" to "Тетрадь Смерти",
    )
    var ok = true
    for ((a, b) in cases) {
        val (ka, kb) = seriesKey(a) to seriesKey(b)
        if (ka != kb) ok = false
        println("[$a] -> $ka   |   [$b] -> $kb   ${if (ka == kb) "OK" else "MISMATCH"}")
    }
    println(if (ok) "seriesKey OK" else "seriesKey FAILED")
}
