        for (v in variants) {
            val got = Key.seriesKey(v)
            if (got != key) { ok = false; println("MISMATCH [$v] -> $got != $key") }
        }
    }
    if (Key.seriesKey("") != "серия" || Key.seriesKey("   ").isBlank()) { ok = false; println("blank key broken") }
    if (Key.seriesKey("Один-Кувалда!") != Key.seriesKey("один кувалда")) { ok = false; println("punctuation broken") }
    if (Key.seriesKey("Падший лисёнок") == Key.seriesKey("Синий замок")) { ok = false; println("distinct series collide") }
    println(if (ok) "seriesKey OK" else "seriesKey FAILED")
}
