package eu.kanade.tachiyomi.data.tts

/**
 * Театральные ремарки и междометия: что произнести и как.
 *
 * Проблема была в двух местах. Первое: ремарка в скобках попадала в синтез
 * либо выбрасывалась совсем, либо произносилась словом — «(вздох)» читалось
 * как «вздох». Второе: `а`, `аа`, `ааа` не различались, хотя означают
 * разное — удивление, попытку закричать, крик. Плюс состояние персонажа
 * (бежит, устал, обессилел, зовёт помощь) вообще не влияло на голос.
 *
 * Здесь ремарки делятся на два вида, и это важно:
 *
 *  * **звук** (вздох, вдох, стон, крик, смех, кашель) — ПРОИЗНОСИТСЯ.
 *    Движок синтеза не умеет вздыхать, поэтому звук передаётся вытянутым
 *    «А-а-а», а характер берёт на себя питч и темп;
 *  * **состояние** (шёпот, бег, усталость, слабость, боль, испуг, злость) —
 *    НЕ произносится, а меняет подачу всей реплики. Произносить слово
 *    «шёпот» вслух нельзя, это сломало бы чтение.
 *
 * Ничего не теряется: неизвестная ремарка с ключевым словом звука
 * произносится, а состояние всегда доходит до голоса как модификатор.
 *
 * Модуль чистый — без Android и без движка, поэтому проверяется на JVM.
 */
object SpeechCue {

    /** Как произнести один кусок реплики. */
    data class Delivery(
        val text: String,
        val pitch: Float = 1.0f,
        val rate: Float = 1.0f,
        val pauseAfterMs: Int = 0,
    )

    /**
     * Звук: что говорить и каким голосом. [words] — ключевые слова ремарки.
     */
    private class Sound(
        val spoken: String,
        val pitch: Float,
        val rate: Float,
        val pauseMs: Int,
        val words: List<String>,
    )

    /** Состояние: только модификатор подачи, ничего не произносится. */
    private class State(
        val pitch: Float,
        val rate: Float,
        val words: List<String>,
    )

    // Порядок важен: первое совпадение выигрывает. «Крик помощи» и «вдох»
    // проверены раньше «крика» и «вздоха», иначе крик о помощи читался бы
    // обычным криком, а вдох — выдохом.
    private val SOUNDS = listOf(
        Sound(
            spoken = "А-а-а! По-мо-ги!",
            pitch = 1.28f,
            rate = 1.10f,
            pauseMs = 420,
            words = listOf(
                "крик помощи", "зовет помощь", "зовёт помощь", "на помощь",
                "помогите", "помоги", "спасите", "спаси",
            ),
        ),
        Sound(
            spoken = "А-а-а!",
            pitch = 1.30f,
            rate = 1.15f,
            pauseMs = 380,
            words = listOf(
                "вопль", "визг", "крик", "кричит", "кричу", "орёт", "орет",
                "воет", "воёт", "рычит", "закричал", "закричала", "вскрикнул",
            ),
        ),
        Sound(
            spoken = "А-а-а...",
            pitch = 0.92f,
            rate = 0.85f,
            pauseMs = 320,
            words = listOf(
                "стон", "стонет", "стонет от боли", "хнычет", "хнычеть",
                "ныть", "поскуливает", "скулит",
            ),
        ),
        Sound(
            spoken = "А-а-а!",
            pitch = 1.05f,
            rate = 0.95f,
            pauseMs = 240,
            words = listOf(
                "вдох", "вдыхает", "задыхается", "хватает воздух",
                "не хватает воздуха", "дышит часто", "задыхаясь",
            ),
        ),
        Sound(
            spoken = "А-а-а...",
            pitch = 0.86f,
            rate = 0.78f,
            pauseMs = 360,
            words = listOf(
                "вздох", "вздыхает", "вздохнув", "выдох", "выдыхает", "устало выдыхает",
            ),
        ),
        Sound(
            spoken = "Ха-ха-ха!",
            pitch = 1.12f,
            rate = 1.12f,
            pauseMs = 260,
            words = listOf(
                "смеется", "смеётся", "смех", "хохочет", "хихикает", "усмехается",
            ),
        ),
        Sound(
            spoken = "Кхм... Кхм!",
            pitch = 0.94f,
            rate = 0.9f,
            pauseMs = 300,
            words = listOf("кашель", "кашляет", "кашлянул", "кашлянуть", "кашлит"),
        ),
    )

