        State(0.92f, 0.86f, listOf("устал", "устала", "усталость", "тяжело дышит", "выдохшийся", "выдохлась", "истощен", "истощён")),
        State(0.88f, 0.80f, listOf("слабость", "вялость", "обессилел", "обессилела", "без сил", "слабый голосом", "едва говорит", "хрипло")),
        State(0.95f, 0.88f, listOf("боль", "болит", "рана", "ранен", "ранена", "испытывает боль")),
        State(0.90f, 1.05f, listOf("испуг", "боится", "боюсь", "страх", "трусит", "дрожит")),
        State(1.12f, 1.12f, listOf("злость", "злится", "ярость", "сердит", "взбешён", "взбешен", "разозлён", "разозлен")),
        State(1.14f, 1.04f, listOf("удивлён", "удивлен", "удивление", "изумлён", "изумлен", "шок", "потрясён", "потрясен")),
    )

    /**
     * Ремарки в скобках: `(вздох)`, `[ааа]`, `*шёпотом*`, а также
     * «курсив» и кавычки. Закрывающая скобка экранирована — без экрана
     * ICU-движок некоторых Android падает прямо на разборе шаблона
     * (см. предупреждение в [SpeechMarkup]).
     */
    private val CUE_SPAN = Regex("""[(\[*]\s*([^()\[\]{}*]{1,60}?)\s*[)\]*]""")

    /**
     * Голые междометия. Длина важна: «а», «аа» и «ааа» — разные звуки.
     * `\b` здесь НЕ подходит (он ASCII-ориентирован и кириллицу не видит),
     * поэтому границы заданы явно через пробел/край строки.
     */
    private val INTERJECTION = Regex(
        """(?<![пПa-zA-ZЁёА-я])([аА]|[аА][аА]|[аА][аА][аА]|[аА][аА][аА][аА]|[аА][хХцЦ]|[уУхХ]|[оОхХ]|[уУ]|[ыЫ]|[мМ][мМ]|[хХ][мМ]|[эЭ][мМ])(?![пПa-zA-ZЁёА-я])""",
    )

    /** Что за звук задан ремаркой, или null. */
    fun soundOf(remark: String): Sound? {
        val low = remark.lowercase()
        return SOUNDS.firstOrNull { s -> s.words.any { low.contains(it) } }
    }

    /** Какое состояние описано в ремарке, или null. */
    fun stateOf(remark: String): State? {
        val low = remark.lowercase()
        return STATES.firstOrNull { s -> s.words.any { low.contains(it) } }
    }

    /**
     * Подставляет вместо ремарок произносимое: звук → вытянутое междометие,
     * состояние → пусто (оно меняет подачу, а не текст). Ремарки без
     * известного ключевого слова — просто снимаются, чтобы синтез не читал
     * их вслух как обычные слова.
     */
    fun render(text: String): String {
        var out = CUE_SPAN.replace(text) { match ->
            val remark = match.groupValues[1]
            soundOf(remark)?.spoken ?: ""
        }
        out = out.replace(Regex("""[ ]+"""), " ")
        return out.replace(Regex("""\s+([,.!?;:…])"""), "$1").trim()
    }

    /**
     * Подача одного междометия по его длине. Три «а» — крик, одно «а» —
     * удивление; раньше они читались одинаково.
     */
    fun interjectionDelivery(word: String): Delivery {
        val core = word.trim().lowercase()
        val letterCount = core.count { it == 'а' }
        val hasTail = core.any { it in "хц" }
        return when {
            hasTail -> Delivery(word, pitch = 1.05f, rate = 0.92f, pauseAfterMs = 220)
            letterCount >= 3 -> Delivery(word, pitch = 1.28f, rate = 1.12f, pauseAfterMs = 300)
            letterCount == 2 -> Delivery(word, pitch = 1.16f, rate = 0.90f, pauseAfterMs = 240)
            else -> Delivery(word, pitch = 1.10f, rate = 0.95f, pauseAfterMs = 180)
        }
    }

    /**
     * Раскладывает реплику на куски со своей подачей: обычный текст идёт
     * как есть, а голые междометия выделяются отдельными кусками, иначе
     * «ааа» читалось бы вместе со следующей фразой общим тоном.
     *
     * Состояние из ремарок умножается на подачу куска: шёпот делает тише и
     * медленнее всё, что после него, а не только само слово «шёпот».
     */
    fun deliveries(sentence: String): List<Delivery> {
        if (sentence.isBlank()) return emptyList()
        val out = mutableListOf<Delivery>()

        val state = CUE_SPAN.findAll(sentence)
            .mapNotNull { stateOf(it.groupValues[1]) }
            .maxByOrNull { it.rate }
        val sp = state?.pitch ?: 1.0f
        val sr = state?.rate ?: 1.0f

        var last = 0
        INTERJECTION.findAll(sentence).forEach { m ->
            val word = m.value
            if (word.count { it == 'а' } == 1 && word.length == 1 && m.range.first == 0) {
                // одиночное «а» в начале фразы — обычное слово, не междометие
            } else {
                val before = sentence.substring(last, m.range.first).trim()
                if (before.isNotBlank()) {
                    out += Delivery(before, sp, sr, defaultPause(before))
                }
                val d = interjectionDelivery(word)
                out += Delivery(d.text, d.pitch * sp, d.rate * sr, d.pauseAfterMs)
                last = m.range.last + 1
            }
        }
        val tail = sentence.substring(last).trim()
        if (tail.isNotBlank()) {
            out += Delivery(tail, sp, sr, defaultPause(tail))
        }
        if (out.isEmpty()) out += Delivery(sentence.trim(), sp, sr, defaultPause(sentence))
        return out
    }

    /** Пауза после куска: та же логика, что в движке, но по самому куску. */
    private fun defaultPause(text: String): Int = when {
        text.endsWith("!") || text.endsWith("?") || text.endsWith("‼") || text.endsWith("⁇") -> 420
        text.endsWith(",") || text.endsWith(";") -> 160
        else -> 260
    }
}

