 * Ремарки убираются (звук превращается в произносимое), состояние
 * становится множителем подачи, а голые междометия выделяются отдельными
 * кусками. Именно так «ааа» перестаёт читаться вместе со следующей
 * фразой общим тоном, а шёпот делает тише и медленнее всю реплику.
 */
fun deliveries(sentence: String): List<Delivery> {
    if (sentence.isBlank()) return emptyList()

    // Состояние: при нескольких ремарках побеждает самое заметное
    // (самая крайняя скорость), чтобы «(устал) (бегом)» не усреднялось.
    val state = CUE_SPAN.findAll(sentence)
        .mapNotNull { stateOf(it.groupValues[1]) }
        .maxByOrNull { kotlin.math.abs(it.rate - 1f) }
    val sp = state?.pitch ?: 1.0f
    val sr = state?.rate ?: 1.0f

    val clean = render(sentence)
    if (clean.isBlank()) return emptyList()

    val out = mutableListOf<Delivery>()
    var last = 0
    CANDIDATE.findAll(clean).forEach { m ->
        if (!isInterjection(m.value)) return@forEach
        // Знаки после междометия («А-а-а!») остаются с ним же, иначе
        // восклицательный знак уедет в отдельный кусок и прочитается
        // как отдельное слово.
        var end = m.range.last + 1
        while (end < clean.length && clean[end] in TAIL_PUNCT) end++
        val head = clean.substring(last, m.range.first).trim()
        if (head.isNotBlank()) out += Delivery(head, sp, sr, defaultPause(head))
        val d = interjectionDelivery(clean.substring(m.range.first, end))
        out += Delivery(d.text, d.pitch * sp, d.rate * sr, d.pauseAfterMs)
        last = end
    }
    val tail = clean.substring(last).trim()
    if (tail.isNotBlank()) out += Delivery(tail, sp, sr, defaultPause(tail))
    if (out.isEmpty()) out += Delivery(clean, sp, sr, defaultPause(clean))
    return out
}

