/**
 * Вопрос к vision-модели по выбранному движку.
 *
 * Умеют не все: локальный кириллический распознаватель и ML Kit работают
 * только с текстом. Для них возвращается null, чтобы вызывающий код
 * продолжил разговор без взгляда на страницу, а не упал.
 */
override suspend fun askAboutImage(image: OcrImage, question: String): String? {
    val text = question.trim()
    if (text.isEmpty()) return null
    return withActiveOperation {
        submitTask(PrioritizedTaskQueue.Priority.HIGH) {
            image.useBitmap { bitmap ->
                when (val type = selectedEngineType()) {
                    EngineType.ZEN_FREE ->
                        (zenFreeEngine ?: ZenFreeOcrEngine().also { zenFreeEngine = it })
                            .askAboutPage(bitmap, text)
                    else -> runCatching {
                        openRouterOrGoogleAsk(type, bitmap, text)
                    }.getOrNull()
                }
            }
        }
    }
}

private suspend fun openRouterOrGoogleAsk(
    type: EngineType,
    bitmap: Bitmap,
    question: String,
): String? = when (type) {
    EngineType.OPENROUTER ->
        (openRouterEngine ?: OpenRouterOcrEngine(context, ocrPreferences).also { openRouterEngine = it })
            .askAboutPage(bitmap, question)
    EngineType.GOOGLE ->
        (googleAiEngine ?: GoogleAiOcrEngine(context, ocrPreferences).also { googleAiEngine = it })
            .askAboutPage(bitmap, question)
    else -> null
}

