package io.kotest.matchers

// Сигнатура повторяет kotest: дополнительный параметр U : T важен, потому
// что именно из-за него `a < b shouldBe true` не находит кандидата.
infix fun <T, U : T> T.shouldBe(expected: U?): T {
    if (this != expected) throw AssertionError("expected <$expected> but was <$this>")
    return this
}

package io.kotest.matchers.collections

infix fun <T> Collection<T>.shouldHaveSize(n: Int): Collection<T> {
    if (size != n) throw AssertionError("expected size <$n> but was <$size>")
    return this
}

