    var pass = 0
    var fail = 0
    for (k in classes) {
        val ctor = k.constructors.first()
        for (fn in k.members) {
            if (fn.annotations.none { it.annotationClass.qualifiedName == "org.junit.jupiter.api.Test" }) continue
            val inst = ctor.call()
            try {
