                 "вздох", "вздыхает", "вздохнув", "выдох", "выдыхает",
             ),
         ),
         Sound(
             spoken = "Ха-ха-ха!",
             pitch = 1.12f,
             rate = 1.12f,
             pauseMs = 260,
             words = listOf(
