     fun `audibility requires a letter or a digit`() {
         SpeechCue.isAudible("Ааа!") shouldBe true
         SpeechCue.isAudible("2024") shouldBe true
         SpeechCue.isAudible("(") shouldBe false
         SpeechCue.isAudible(" ) ") shouldBe false
