package eu.kohesive.tachiyomi.data.ai

import org.json.JSONArray
import org.json.JSONObject

/**
 * Форма ответа и эндпоинт у opencode Zen зависят от семейства модели, а не
 * от того, откуда послали запрос. Игнорировать это нельзя: Claude на
 * `/chat/completions` не отвечает вовсе, поэтому модель выглядит «сломанной».
 *
 * Здесь собраны и маршрутизация, и разбор ответа — обе части чистые, без
 * сети и без Android, поэтому их можно проверять тестами.
 */
object ZenProtocol {

    /** Куда уходит запрос для конкретной модели. */
    enum class Family(val endpoint: String) {
        /** OpenAI-совместимый, основная масса моделей. */
        CHAT("/chat/completions"),

        /** GPT, Grok, Muse Spark — OpenAI Responses API. */
        RESPONSES("/responses"),

        /** Claude — сооб��ения Anthropic. */
        MESSAGES("/messages"),

        /** Gemini — свой путь с именем модели. */
        GEMINI(""),

        /** Jev — System One, не чат: возвращает оценки состояния. */
        SYSTEM_ONE("/systemone"),
    }

    /**
     * Семейство модели по её id.
     *
     * Порядок проверок важен: `*-flash` встречается и у Gemini, и у Qwen, и
     * у Nemotron, поэтому сначала отсекаем то, что уникально, и только потом
     * смотрим на суффикс.
     */
    fun familyOf(model: String): Family {
        val id = model.trim().lowercase()
        return when {
            id.startsWith("jev-") -> Family.SYSTEM_ONE
            id.startsWith("claude-") -> Family.MESSAGES
            id.startsWith("gpt-") || id.startsWith("codex") -> Family.RESPONSES
            id.startsWith("grok-") || id.startsWith("muse-spark") -> Family.RESPONSES
            id.startsWith("gemini-") -> Family.GEMINI
            else -> Family.CHAT
        }
    }

    /** Полный URL запроса для модели. */
    fun urlFor(baseUrl: String, model: String): String {
        val base = baseUrl.trimEnd('/')
        return when (val f = familyOf(model)) {
            Family.GEMINI -> "$base/models/$model:generateContent"
            else -> base + f.endpoint
        }
    }

    /**
     * Тело запроса в форме, которую ждёт эндпоинт. Общая часть — модель,
     * промпт и лимит токенов; различаются они только именем полей и тем,
     * что у Anthropic системный промпт отдельный.
     */
    fun requestBody(
        model: String,
        userPrompt: String,
        systemPrompt: String?,
        maxTokens: Int,
    ): String {
        val system = systemPrompt.orEmpty()
        val json = JSONObject()
        json.put("model", model)
        when (familyOf(model)) {
            // У Anthropic system — отдельное поле, а не сообщение в массиве.
            Family.MESSAGES -> {
                json.put("max_tokens", maxTokens.coerceAtLeast(1))
                json.put("system", system)
                json.put(
                    "messages",
                    JSONArray().put(
                        JSONObject().put("role", "user").put("content", userPrompt),
                    ),
                )
            }
            // У Gemini systemPrompt идёт в systemInstruction, а ответ приходит
            // в candidates[].content.parts[].text.
            Family.GEMINI -> {
                if (system.isNotBlank()) {
                    json.put(
                        "systemInstruction",
                        JSONObject().put("parts", JSONArray().put(JSONObject().put("text", system))),
                    )
                }
                json.put(
                    "contents",
                    JSONArray().put(
                        JSONObject().put(
                            "parts",
                            JSONArray().put(JSONObject().put("text", userPrompt)),
                        ),
                    ),
                )
                json.put(
                    "generationConfig",
                    JSONObject().put("maxOutputTokens", maxTokens.coerceAtLeast(1)),
                )
            }
            Family.RESPONSES -> {
                if (system.isNotBlank()) {
                    json.put("instructions", system)
                }
                json.put(
                    "input",
                    JSONArray().put(
                        JSONObject().put("role", "user").put("content", userPrompt),
                    ),
                )
                json.put("max_output_tokens", maxTokens.coerceAtLeast(1))
            }
            else -> {
                if (system.isNotBlank()) {
                    json.put(
                        "messages",
                        JSONArray()
                            .put(JSONObject().put("role", "system").put("content", system))
                            .put(JSONObject().put("role", "user").put("content", userPrompt)),
                    )
                } else {
                    json.put(
                        "messages",
                        JSONArray().put(
                            JSONObject().put("role", "user").put("content", userPrompt),
                        ),
                    )
                }
                json.put("max_tokens", maxTokens.coerceAtLeast(1))
                json.put("stream", false)
            }
        }
        return json.toString()
    }

    /** Разобранный ответ модели. */
    data class Parsed(
        val content: String?,
        val reasoning: String?,
        val tokens: Int,
        val complete: Boolean,
    )

    /**
     * Текст в поле, который может содержать JSON null.
     *
     * org.json на Android возвращает для JSON null строку "null", а не пустую
     * строку. Из-за этого в чате появлялось «🤔 null» и «null» вместо ответа.
     * Пустая строка, пробелы и литерал "null" — это всё отсутствие значения.
     */
    fun textOrNull(value: Any?): String? = when (value) {
        null, JSONObject.NULL -> null
        is String -> value.trim().takeIf { it.isNotBlank() && !it.equals("null", ignoreCase = true) }
        else -> value.toString().trim().takeIf { it.isNotBlank() && !it.equals("null", ignoreCase = true) }
    }

    private fun JSONObject.text(key: String): String? = textOrNull(opt(key))

    /** Склеивает текстовые куски вложенного массива content. */
    private fun joinText(array: JSONArray?): String? {
        if (array == null) return null
        val sb = StringBuilder()
        for (i in 0 until array.length()) {
            val t = textOrNull(array.opt(i))
            if (!t.isNullOrBlank()) sb.append(t)
        }
        return sb.toString().trim().takeIf { it.isNotBlank() }
    }

    /**
     * Разбор ответа любого из известных форматов.
     *
     * Порядок не важен — у каждой формы свой ключ, который не пересекается с
     * остальными, — но явная ветка по семейству читается проще, чем поиск
     * «какая форма пришла».
     */
    fun parse(body: String, model: String): Parsed {
        val root = JSONObject(body)
        return when (familyOf(model)) {
            Family.CHAT -> parseChat(root)
            Family.RESPONSES -> parseResponses(root)
            Family.MESSAGES -> parseMessages(root)
            Family.GEMINI -> parseGemini(root)
            // Jev не чат: у него нет ни текста, ни размышлений.
            Family.SYSTEM_ONE -> Parsed(null, null, 0, true)
        }
    }

    private fun parseChat(root: JSONObject): Parsed {
        val choice = root.optJSONArray("choices")?.optJSONObject(0)
        val message = choice?.optJSONObject("message")
        val finish = choice?.text("finish_reason").orEmpty()
        return Parsed(
            content = message?.text("content"),
            // nemotron отдаёт «reasoning», hy3 — «reasoning_content».
            reasoning = message?.text("reasoning")
                ?: message?.text("reasoning_content")
                ?: root.text("reasoning"),
            tokens = root.optJSONObject("usage")?.optInt("total_tokens", 0) ?: 0,
            complete = finish != "length",
        )
    }

    private fun parseResponses(root: JSONObject): Parsed {
        val reasoning = StringBuilder()
        val content = StringBuilder()
        val output = root.optJSONArray("output")
        if (output != null) {
            for (i in 0 until output.length()) {
                val item = output.optJSONObject(i) ?: continue
                when (item.optString("type")) {
                    // Размышления приходят отдельным типом и в отдельном поле.
                    "reasoning" -> reasoning.append(item.text("summary").orEmpty())
                        .append(item.text("text").orEmpty())
                    "message" -> {
                        val parts = item.optJSONArray("content")
                        for (j in 0 until (parts?.length() ?: 0)) {
                            val part = parts?.optJSONObject(j)
                            content.append(
                                when (part?.optString("type")) {
                                    "output_text" -> part.text("text").orEmpty()
                                    // Некоторые ответы кладут текст прямо в part.
                                    "text" -> part.text("text").orEmpty()
                                    else -> part?.text("text").orEmpty()
                                },
                            )
                        }
                    }
                }
            }
        }
        val out = content.toString().trim()
        return Parsed(
            content = out.ifBlank { root.text("output_text") },
            reasoning = reasoning.toString().trim().takeIf { it.isNotBlank() }
                ?: root.text("reasoning"),
            tokens = root.optJSONObject("usage")?.optInt("total_tokens", 0) ?: 0,
            complete = root.text("status")?.lowercase() != "incomplete",
        )
    }

    private fun parseMessages(root: JSONObject): Parsed {
        val content = StringBuilder()
        val reasoning = StringBuilder()
        val blocks = root.optJSONArray("content")
        if (blocks != null) {
            for (i in 0 until blocks.length()) {
                val block = blocks.optJSONObject(i) ?: continue
                when (block.optString("type")) {
                    "text" -> content.append(block.text("text").orEmpty())
                    // Claude отдаёт размышления блоком thinking.
                    "thinking", "redacted_thinking" ->
                        reasoning.append(block.text("thinking").orEmpty())
                }
            }
        }
        val usage = root.optJSONObject("usage")
        return Parsed(
            content = content.toString().trim().takeIf { it.isNotBlank() },
            reasoning = reasoning.toString().trim().takeIf { it.isNotBlank() },
            tokens = usage?.optInt("input_tokens", 0)?.plus(usage.optInt("output_tokens", 0)) ?: 0,
            complete = root.text("stop_reason")?.lowercase() != "max_tokens",
        )
    }

    private fun parseGemini(root: JSONObject): Parsed {
        val candidate = root.optJSONArray("candidates")?.optJSONObject(0)
        val parts = candidate?.optJSONObject("content")?.optJSONArray("parts")
        // У Gemini размышления помечены флагом thought у части текста.
        val content = StringBuilder()
        val reasoning = StringBuilder()
        if (parts != null) {
            for (i in 0 until parts.length()) {
                val part = parts.optJSONObject(i) ?: continue
                val t = textOrNull(part.opt("text")) ?: continue
                if (part.optBoolean("thought", false)) reasoning.append(t) else content.append(t)
            }
        }
        return Parsed(
            content = content.toString().trim().takeIf { it.isNotBlank() },
            reasoning = reasoning.toString().trim().takeIf { it.isNotBlank() },
            tokens = root.optJSONObject("usageMetadata")?.optInt("totalTokenCount", 0) ?: 0,
            complete = candidate?.text("finishReason")?.uppercase() != "MAX_TOKENS",
        )
    }
}

package eu.kohesive.tachiyomi.data.ai

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.booleanOrNull
import kotlinx.serialization.json.contentOrNull
import kotlinx.serialization.json.intOrNull
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive

/**
 * Форма ответа и эндпоинт у opencode Zen зависят от семейства модели, а не
 * от того, откуда послали запрос. Игнорировать это нельзя: Claude на
 * `/chat/completions` не отвечает вовсе, поэтому модель выглядит «сломанной».
 *
 * Здесь собраны и маршрутизация, и разбор ответа. Обе части чистые, без сети
 * и без Android, поэтому их можно проверять тестами. Разбор сделан на
 * kotlinx.serialization, а не на org.json: org.json в юнит-тестах Android
 * нерабочий («not mocked»).
 */
object ZenProtocol {

    private val json = Json { ignoreUnknownKeys = true; isLenient = true }

    /** Куда уходит запрос для конкретной модели. */
    enum class Family(val endpoint: String) {
        /** OpenAI-совместимый, основная масса моделей. */
        CHAT("/chat/completions"),

        /** GPT, Grok, Muse Spark — OpenAI Responses API. */
        RESPONSES("/responses"),

        /** Claude — сообщения Anthropic. */
        MESSAGES("/messages"),

        /** Gemini — свой путь с именем модели. */
        GEMINI(""),

        /** Jev — System One, не чат: возвращает оценки состояния. */
        SYSTEM_ONE("/systemone"),
    }

    /**
     * Семейство модели по её id.
     *
     * Порядок проверок важен: `flash` встречается и у Gemini, и у Qwen, и у
     * Nemotron, поэтому сначала отсекаем то, что уникально, и только потом
     * смотрим на остаток.
     */
    fun familyOf(model: String): Family {
        val id = model.trim().lowercase()
        return when {
            id.startsWith("jev-") -> Family.SYSTEM_ONE
            id.startsWith("claude-") -> Family.MESSAGES
            id.startsWith("gpt-") || id.startsWith("codex") -> Family.RESPONSES
            id.startsWith("grok-") || id.startsWith("muse-spark") -> Family.RESPONSES
            id.startsWith("gemini-") -> Family.GEMINI
            else -> Family.CHAT
        }
    }

    /** Полный URL запроса для модели. */
    fun urlFor(baseUrl: String, model: String): String {
        val base = baseUrl.trimEnd('/')
        return when (familyOf(model)) {
            Family.GEMINI -> "$base/models/$model:generateContent"
            else -> base + f.endpoint.let { it }
        }
    }

    /** Тело запроса в форме, которую ждёт эндпоинт. */
    fun requestBody(
        model: String,
        userPrompt: String,
        systemPrompt: String?,
        maxTokens: Int,
    ): JsonObject {
        val system = systemPrompt.orEmpty()
        val limit = maxTokens.coerceAtLeast(1)
        fun text(value: String) = buildJsonObject {
            put("type", "text")
            put("text", value)
        }
        fun userMsg(value: String) = buildJsonObject {
            put("role", "user")
            put("content", value)
        }
        return when (familyOf(model)) {
            // У Anthropic system — отдельное поле, а не сообщение в массиве.
            Family.MESSAGES -> buildJsonObject {
                put("model", model)
                put("max_tokens", limit)
                put("system", system)
                put("messages", JsonArray(listOf(userMsg(userPrompt))))
            }
            // У Gemini системная инструкция отдельная, ответ приходит в
            // candidates[].content.parts[].
            Family.GEMINI -> buildJsonObject {
                put(
                    "contents",
                    JsonArray(
                        listOf(
                            buildJsonObject {
                                put("parts", JsonArray(listOf(text(userPrompt))))
                            },
                        ),
                    ),
                )
                if (system.isNotBlank()) {
                    put(
                        "systemInstruction",
                        buildJsonObject { put("parts", JsonArray(listOf(text(system)))) },
                    )
                }
                put(
                    "generationConfig",
                    buildJsonObject { put("maxOutputTokens", limit) },
                )
            }
            // У Responses API инструкции отдельным полем, а не сообщением.
            Family.RESPONSES -> buildJsonObject {
                put("model", model)
                if (system.isNotBlank()) put("instructions", system)
                put("input", JsonArray(listOf(userMsg(userPrompt))))
                put("max_output_tokens", limit)
            }
            else -> buildJsonObject {
                put("model", model)
                val messages = buildList {
                    if (system.isNotBlank()) {
                        add(
                            buildJsonObject {
                                put("role", "system")
                                put("content", system)
                            },
                        )
                    }
                    add(userMsg(userPrompt))
                }
                put("messages", JsonArray(messages))
                put("max_tokens", limit)
                put("stream", false)
            }
        }
    }

    /** Разобранный ответ модели. */
    data class Parsed(
        val content: String?,
        val reasoning: String?,
        val tokens: Int,
        val complete: Boolean,
    )

    /**
     * Текст в поле, которое может оказаться пустым.
     *
     * Отдельно отсекается строка "null": провайдеры шлют её и как JSON null, и
     * как обычную строку, а читатель видел в чате «🤔 null» вместо ответа.
     */
    fun textOrNull(element: JsonElement?): String? {
        val raw = element?.jsonPrimitive?.contentOrNull ?: return null
        val t = raw.trim()
        return t.takeIf { it.isNotBlank() && !it.equals("null", ignoreCase = true) }
    }

    private fun JsonObject.text(key: String): String? = textOrNull(this[key])

    private fun StringBuilder.appendText(value: String?) {
        if (!value.isNullOrBlank()) append(value)
    }

    private fun build(vararg parts: StringBuilder): String? =
        parts.joinToString("") { it.toString() }.trim().takeIf { it.isNotBlank() }

    /**
     * Разбор ответа любого из известных форматов. У каждой формы свои ключи,
     * не пересекающиеся с остальными, поэтому явная ветка по семейству читается
     * проще, чем поиск «какая форма пришла».
     */
    fun parse(body: String, model: String): Parsed {
        val root = runCatching { json.parseToJsonElement(body) as? JsonObject }.getOrNull()
            ?: return Parsed(null, null, 0, true)
        return when (familyOf(model)) {
            Family.CHAT -> parseChat(root)
            Family.RESPONSES -> parseResponses(root)
            Family.MESSAGES -> parseMessages(root)
            Family.GEMINI -> parseGemini(root)
            // Jev не чат: у него нет ни текста, ни размышлений.
            Family.SYSTEM_ONE -> Parsed(null, null, 0, true)
        }
    }

    private fun JsonObject.array(key: String): JsonArray? = this[key] as? JsonArray

    private fun JsonObject.obj(key: String): JsonObject? = this[key] as? JsonObject

    private fun JsonObject.str(key: String): String? = textOrNull(this[key])

    private fun JsonObject.int(key: String): Int = this[key]?.jsonPrimitive?.intOrNull ?: 0

    private fun JsonObject.flag(key: String): Boolean = this[key]?.jsonPrimitive?.booleanOrNull ?: false

    private fun parseChat(root: JsonObject): Parsed {
        val choice = root.array("choices")?.firstOrNull() as? JsonObject
        val message = choice?.obj("message")
        val finish = choice?.str("finish_reason").orEmpty()
        return Parsed(
            content = message?.str("content"),
            // nemotron отдаёт «reasoning», hy3 — «reasoning_content».
            reasoning = message?.str("reasoning")
                ?: message?.str("reasoning_content")
                ?: root.str("reasoning"),
            tokens = root.obj("usage")?.int("total_tokens") ?: 0,
            complete = finish != "length",
        )
    }

    private fun parseResponses(root: JsonObject): Parsed {
        val content = StringBuilder()
        val reasoning = StringBuilder()
        for (item in root.array("output").orEmpty()) {
            val obj = item as? JsonObject ?: continue
            when (obj.str("type")) {
                // Размышления приходят отдельным типом, текстом или списком.
                "reasoning" -> {
                    reasoning.appendText(obj.str("text"))
                    for (part in obj.array("summary").orEmpty()) {
                        reasoning.appendText((part as? JsonObject)?.str("text"))
                    }
                }
                "message" -> {
                    for (part in obj.array("content").orEmpty()) {
                        val p = part as? JsonObject ?: continue
                        content.appendText(p.str("text"))
                    }
                }
            }
        }
        return Parsed(
            content = build(content) ?: root.str("output_text"),
            reasoning = build(reasoning) ?: root.str("reasoning"),
            tokens = root.obj("usage")?.int("total_tokens") ?: 0,
            complete = root.str("status")?.lowercase() != "incomplete",
        )
    }

    private fun parseMessages(root: JsonObject): Parsed {
        val content = StringBuilder()
        val reasoning = StringBuilder()
        for (block in root.array("content").orEmpty()) {
            val b = block as? JsonObject ?: continue
            when (b.str("type")) {
                "text" -> content.appendText(b.str("text"))
                // Claude отдаёт размышления отдельным блоком thinking.
                "thinking", "redacted_thinking" -> reasoning.appendText(b.str("thinking"))
            }
        }
        val usage = root.obj("usage")
        return Parsed(
            content = build(content),
            reasoning = build(reasoning),
            tokens = (usage?.int("input_tokens") ?: 0) + (usage?.int("output_tokens") ?: 0),
            complete = root.str("stop_reason")?.lowercase() != "max_tokens",
        )
    }

    private fun parseGemini(root: JsonObject): Parsed {
        val candidate = root.array("candidates")?.firstOrNull() as? JsonObject
        val parts = candidate?.obj("content")?.array("parts")
        val content = StringBuilder()
        val reasoning = StringBuilder()
        for (part in parts.orEmpty()) {
            val p = part as? JsonObject ?: continue
            val t = p.str("text") ?: continue
            // Размышления помечены флагом thought у самой части текста.
            if (p.flag("thought")) reasoning.appendText(t) else content.appendText(t)
        }
        return Parsed(
            content = build(content),
            reasoning = build(reasoning),
            tokens = root.obj("usageMetadata")?.int("totalTokenCount") ?: 0,
            complete = candidate?.str("finishReason")?.uppercase() != "MAX_TOKENS",
        )
    }
}

private fun buildJsonObject(block: kotlinx.serialization.json.JsonObjectBuilder.() -> Unit): JsonObject =
    kotlinx.serialization.json.buildJsonObject(block)

private fun JsonArray.firstOrNull(): JsonElement? = if (isEmpty()) null else this[0]

package eu.kohesive.tachiyomi.data.ai

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.booleanOrNull
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.contentOrNull
import kotlinx.serialization.json.intOrNull

/**
 * Форма ответа и эндпоинт у opencode Zen зависят от семейства модели, а не
 * от того, откуда послали запрос. Игнорировать это нельзя: Claude на
 * `/chat/completions` не отвечает вовсе, поэтому модель выглядит «сломанной».
 *
 * Здесь собраны и маршрутизация, и разбор ответа. Обе части чистые, без сети
 * и без Android, поэтому их можно проверять тестами. Разбор сделан на
 * kotlinx.serialization, а не на org.json: org.json в юнит-тестах Android
 * нерабочий («not mocked»).
 */
object ZenProtocol {

    private val json = Json { ignoreUnknownKeys = true; isLenient = true }

    /** Куда уходит запрос для конкретной модели. */
    enum class Family(val endpoint: String) {
        /** OpenAI-совместимый, основная масса моделей. */
        CHAT("/chat/completions"),

        /** GPT, Grok, Muse Spark — OpenAI Responses API. */
        RESPONSES("/responses"),

        /** Claude — сообщения Anthropic. */
        MESSAGES("/messages"),

        /** Gemini — свой путь с именем модели. */
        GEMINI(""),

        /** Jev — System One, не чат: возвращает оценки состояния. */
        SYSTEM_ONE("/systemone"),
    }

    /**
     * Семейство модели по её id.
     *
     * Порядок проверок важен: «flash» встречается и у Gemini, и у Qwen, и у
     * Nemotron, поэтому сначала отсекаем то, что уникально, и только потом
     * смотрим на остаток.
     */
    fun familyOf(model: String): Family {
        val id = model.trim().lowercase()
        return when {
            id.startsWith("jev-") -> Family.SYSTEM_ONE
            id.startsWith("claude-") -> Family.MESSAGES
            id.startsWith("gpt-") || id.startsWith("codex") -> Family.RESPONSES
            id.startsWith("grok-") || id.startsWith("muse-spark") -> Family.RESPONSES
            id.startsWith("gemini-") -> Family.GEMINI
            else -> Family.CHAT
        }
    }

    /** Полный URL запроса для модели. */
    fun urlFor(baseUrl: String, model: String): String {
        val base = baseUrl.trimEnd('/')
        return when (familyOf(model)) {
            Family.GEMINI -> "$base/models/$model:generateContent"
            else -> base + familyOf(model).endpoint
        }
    }

    /** Тело запроса в форме, которую ждёт эндпоинт. */
    fun requestBody(
        model: String,
        userPrompt: String,
        systemPrompt: String?,
        maxTokens: Int,
    ): JsonObject {
        val system = systemPrompt.orEmpty()
        val limit = maxTokens.coerceAtLeast(1)
        val part = { value: String ->
            buildJsonObject {
                put("type", "text")
                put("text", value)
            }
        }
        val userMessage = { value: String ->
            buildJsonObject {
                put("role", "user")
                put("content", value)
            }
        }
        return when (familyOf(model)) {
            // У Anthropic system — отдельное поле, а не сообщение в массиве.
            Family.MESSAGES -> buildJsonObject {
                put("model", model)
                put("max_tokens", limit)
                put("system", system)
                put("messages", JsonArray(listOf(userMessage(userPrompt))))
            }
            // У Gemini системная инструкция отдельная, ответ приходит в
            // candidates[].content.parts[].
            Family.GEMINI -> buildJsonObject {
                put(
                    "contents",
                    JsonArray(
                        listOf(
                            buildJsonObject { put("parts", JsonArray(listOf(part(userPrompt)))) },
                        ),
                    ),
                )
                if (system.isNotBlank()) {
                    put(
                        "systemInstruction",
                        buildJsonObject { put("parts", JsonArray(listOf(part(system)))) },
                    )
                }
                put("generationConfig", buildJsonObject { put("maxOutputTokens", limit) })
            }
            // У Responses API инструкции отдельным полем, а не сообщением.
            Family.RESPONSES -> buildJsonObject {
                put("model", model)
                if (system.isNotBlank()) put("instructions", system)
                put("input", JsonArray(listOf(userMessage(userPrompt))))
                put("max_output_tokens", limit)
            }
            else -> buildJsonObject {
                put("model", model)
                val messages = buildList {
                    if (system.isNotBlank()) {
                        add(
                            buildJsonObject {
                                put("role", "system")
                                put("content", system)
                            },
                        )
                    }
                    add(userMessage(userPrompt))
                }
                put("messages", JsonArray(messages))
                put("max_tokens", limit)
                put("stream", false)
            }
        }
    }

    /** Разобранный ответ модели. */
    data class Parsed(
        val content: String?,
        val reasoning: String?,
        val tokens: Int,
        val complete: Boolean,
    )

    /**
     * Текст в поле, которое может оказаться пустым.
     *
     * Отдельно отсекается строка "null": провайдеры шлют её и как JSON null, и
     * как обычную строку, а читатель видел в чате «🤔 null» вместо ответа.
     */
    fun textOrNull(element: JsonElement?): String? {
        val raw = (element as? JsonPrimitive)?.contentOrNull ?: return null
        val t = raw.trim()
        return t.takeIf { it.isNotBlank() && !it.equals("null", ignoreCase = true) }
    }

    /**
     * Разбор ответа любого из известных форматов. У каждой формы свои ключи,
     * не пересекающиеся с остальными, поэтому явная ветка по семейству читается
     * проще, чем поиск «какая форма пришла».
     */
    fun parse(body: String, model: String): Parsed {
        val root = runCatching { json.parseToJsonElement(body) as? JsonObject }.getOrNull()
            ?: return Parsed(null, null, 0, true)
        return when (familyOf(model)) {
            Family.CHAT -> parseChat(root)
            Family.RESPONSES -> parseResponses(root)
            Family.MESSAGES -> parseMessages(root)
            Family.GEMINI -> parseGemini(root)
            // Jev не чат: у него нет ни текста, ни размышлений.
            Family.SYSTEM_ONE -> Parsed(null, null, 0, true)
        }
    }

    private fun str(key: String): String? = textOrNull(this[key])

    private fun int(key: String): Int = (this[key] as? JsonPrimitive)?.intOrNull ?: 0

    private fun flag(key: String): Boolean =
        (this[key] as? JsonPrimitive)?.booleanOrNull ?: false

    private fun array(key: String): List<JsonElement> = this[key] as? JsonArray ?: emptyList()

    private fun obj(key: String): JsonObject? = this[key] as? JsonObject

    private fun firstObject(key: String): JsonObject? = array(key).firstOrNull() as? JsonObject

    private fun join(vararg parts: StringBuilder): String? =
        parts.joinToString("") { it.toString() }
            .trim()
            .takeIf { it.isNotBlank() }

    private fun StringBuilder.add(value: String?) {
        if (!value.isNullOrBlank()) append(value)
    }

    private fun parseChat(root: JsonObject): Parsed {
        val choice = root.firstObject("choices")
        val message = choice?.obj("message")
        val finish = choice?.str("finish_reason").orEmpty()
        return Parsed(
            content = message?.str("content"),
            // nemotron отдаёт «reasoning», hy3 — «reasoning_content».
            reasoning = message?.str("reasoning")
                ?: message?.str("reasoning_content")
                ?: root.str("reasoning"),
            tokens = root.obj("usage")?.int("total_tokens") ?: 0,
            complete = finish != "length",
        )
    }

    private fun parseResponses(root: JsonObject): Parsed {
        val content = StringBuilder()
        val reasoning = StringBuilder()
        for (item in root.array("output")) {
            val obj = item as? JsonObject ?: continue
            when (obj.str("type")) {
                // Размышления приходят отдельным типом, текстом или списком.
                "reasoning" -> {
                    reasoning.add(obj.str("text"))
                    for (part in obj.array("summary")) {
                        reasoning.add((part as? JsonObject)?.str("text"))
                    }
                }
                "message" -> {
                    for (part in obj.array("content")) {
                        content.add((part as? JsonObject)?.str("text"))
                    }
                }
            }
        }
        return Parsed(
            content = join(content) ?: root.str("output_text"),
            reasoning = join(reasoning) ?: root.str("reasoning"),
            tokens = root.obj("usage")?.int("total_tokens") ?: 0,
            complete = root.str("status")?.lowercase() != "incomplete",
        )
    }

    private fun parseMessages(root: JsonObject): Parsed {
        val content = StringBuilder()
        val reasoning = StringBuilder()
        for (block in root.array("content")) {
            val b = block as? JsonObject ?: continue
            when (b.str("type")) {
                "text" -> content.add(b.str("text"))
                // Claude отдаёт размышления отдельным блоком thinking.
                "thinking", "redacted_thinking" -> reasoning.add(b.str("thinking"))
            }
        }
        val usage = root.obj("usage")
        return Parsed(
            content = join(content),
            reasoning = join(reasoning),
            tokens = (usage?.int("input_tokens") ?: 0) + (usage?.int("output_tokens") ?: 0),
            complete = root.str("stop_reason")?.lowercase() != "max_tokens",
        )
    }

    private fun parseGemini(root: JsonObject): Parsed {
        val candidate = root.firstObject("candidates")
        val parts = candidate?.obj("content")?.array("parts").orEmpty()
        val content = StringBuilder()
        val reasoning = StringBuilder()
        for (part in parts) {
            val p = part as? JsonObject ?: continue
            val t = p.str("text") ?: continue
            // Размышления помечены флагом thought у самой части текста.
            if (p.flag("thought")) reasoning.add(t) else content.add(t)
        }
        return Parsed(
            content = join(content),
            reasoning = join(reasoning),
            tokens = root.obj("usageMetadata")?.int("totalTokenCount") ?: 0,
            complete = candidate?.str("finishReason")?.uppercase() != "MAX_TOKENS",
        )
    }
}

package eu.kohesive.tachiyomi.data.ai

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertNotNull
import org.junit.jupiter.api.Assertions.assertNull
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

/**
 * Протокол opencode Zen: эндпоинт по семейству модели и разбор ответа.
 *
 * Главное, что тут закрывается, — «размышляют null». Размышления у разных
 * семейств лежат в разных местах (`reasoning`, `reasoning_content`, блок
 * `thinking`, флаг `thought`), и раньше читался только `choices[0].message`,
 * поэтому всё остальное молча терялось.
 */
class ZenProtocolTest {

    @Test
    fun `each model family is sent to its own endpoint`() {
        // Отправлять Claude в /chat/completions — значит не получить ответа
        // вовсе и увидеть модель как сломанную.
        assertEquals(ZenProtocol.Family.CHAT, ZenProtocol.familyOf("big-pickle"))
        assertEquals(ZenProtocol.Family.CHAT, ZenProtocol.familyOf("mimo-v2.6-flash-free"))
        assertEquals(ZenProtocol.Family.CHAT, ZenProtocol.familyOf("nemotron-3-ultra-free"))
        assertEquals(ZenProtocol.Family.CHAT, ZenProtocol.familyOf("qwen3.8-max"))
        assertEquals(ZenProtocol.Family.CHAT, ZenProtocol.familyOf("glm-5.3"))

        assertEquals(ZenProtocol.Family.RESPONSES, ZenProtocol.familyOf("gpt-6-astra"))
        assertEquals(ZenProtocol.Family.RESPONSES, ZenProtocol.familyOf("grok-4.7"))
        assertEquals(ZenProtocol.Family.RESPONSES, ZenProtocol.familyOf("muse-spark-1.3"))

        assertEquals(ZenProtocol.Family.MESSAGES, ZenProtocol.familyOf("claude-opus-5-5"))
        assertEquals(ZenProtocol.Family.GEMINI, ZenProtocol.familyOf("gemini-3.8-flash"))
        assertEquals(ZenProtocol.Family.SYSTEM_ONE, ZenProtocol.familyOf("jev-1.13-free"))

        // Регистр и пробелы не должны ломать определение семейства.
        assertEquals(ZenProtocol.Family.MESSAGES, ZenProtocol.familyOf("  Claude-Opus-5  "))
    }

    @Test
    fun `url is built for the family of the model`() {
        val base = "https://opencode.ai/zen/v1"
        assertEquals("$base/chat/completions", ZenProtocol.urlFor(base, "big-pickle"))
        assertEquals("$base/responses", ZenProtocol.urlFor(base, "gpt-6-sol"))
        assertEquals("$base/messages", ZenProtocol.urlFor(base, "claude-sonnet-5"))
        assertEquals(
            "$base/models/gemini-3.8-flash:generateContent",
            ZenProtocol.urlFor(base, "gemini-3.8-flash"),
        )
        // Лишний слэш в базе не должен давать двойной.
        assertEquals("$base/messages", ZenProtocol.urlFor("$base/", "claude-sonnet-5"))
    }

    @Test
    fun `chat answer is parsed with both reasoning spellings`() {
        val nemotron = ZenProtocol.parse(
            """{"choices":[{"message":{"content":"Привет","reasoning":"Думаю о погоде"}}],
               "usage":{"total_tokens":12}}""",
            "nemotron-3-ultra-free",
        )
        assertEquals("Привет", nemotron.content)
        assertEquals("Думаю о погоде", nemotron.reasoning)
        assertEquals(12, nemotron.tokens)
        assertTrue(nemotron.complete)

        val hy = ZenProtocol.parse(
            """{"choices":[{"message":{"content":"Привет","reasoning_content":"Размышляю"}}]}""",
            "hy3",
        )
        assertEquals("Размышляю", hy.reasoning)
    }

    @Test
    fun `claude reasoning comes as a thinking block`() {
        // Раньше блок thinking не читался вовсе, и в чате было «🤔 null».
        val parsed = ZenProtocol.parse(
            """{"content":[{"type":"thinking","thinking":"Сначала подумать"},
                          {"type":"text","text":"Вот ответ"}],
               "usage":{"input_tokens":5,"output_tokens":7},
               "stop_reason":"end_turn"}""",
            "claude-opus-5",
        )
        assertEquals("Вот ответ", parsed.content)
        assertEquals("Сначала подумать", parsed.reasoning)
        assertEquals(12, parsed.tokens)
        assertTrue(parsed.complete)
    }

    @Test
    fun `responses reasoning is a separate output item`() {
        val parsed = ZenProtocol.parse(
            """{"output":[{"type":"reasoning","summary":[{"type":"summary_text","text":"Ход мысли"}]},
                          {"type":"message","content":[{"type":"output_text","text":"Итог"}]}],
               "usage":{"total_tokens":30},"status":"completed"}""",
            "gpt-6-sol",
        )
        assertEquals("Итог", parsed.content)
        assertEquals("Ход мысли", parsed.reasoning)
        assertEquals(30, parsed.tokens)
    }

    @Test
    fun `gemini marks reasoning with a thought flag`() {
        val parsed = ZenProtocol.parse(
            """{"candidates":[{"content":{"parts":[
                 {"text":"Обдумываю","thought":true},
                 {"text":"Ответ"}]},"finishReason":"STOP"}],
               "usageMetadata":{"totalTokenCount":9}}""",
            "gemini-3.8-flash",
        )
        assertEquals("Ответ", parsed.content)
        assertEquals("Обдумываю", parsed.reasoning)
        assertEquals(9, parsed.tokens)
    }

    @Test
    fun `literal null never reaches the reader`() {
        // Тот самый баг со скриншота: вместо размышлений показывалось «null».
        assertNull(ZenProtocol.textOrNull(null))
        assertNull(ZenProtocol.textOrNull(kotlinx.serialization.json.JsonNull))
        assertNull(ZenProtocol.textOrNull(kotlinx.serialization.json.JsonPrimitive("null")))
        assertNull(ZenProtocol.textOrNull(kotlinx.serialization.json.JsonPrimitive("  ")))
        assertEquals("текст", ZenProtocol.textOrNull(kotlinx.serialization.json.JsonPrimitive("текст")))

        val parsed = ZenProtocol.parse(
            """{"choices":[{"message":{"content":"Привет","reasoning":null}}]}""",
            "big-pickle",
        )
        assertEquals("Привет", parsed.content)
        assertNull(parsed.reasoning)
    }

    @Test
    fun `broken answer does not throw`() {
        // Мусор в ответе не должен ронять разбор: лучше пустой результат,
        // чем исключение в фоне.
        val parsed = ZenProtocol.parse("не json вовсе", "big-pickle")
        assertNull(parsed.content)

        val empty = ZenProtocol.parse("{}", "claude-opus-5")
        assertNull(empty.content)
        assertNull(empty.reasoning)
    }

    @Test
    fun `truncated answers are marked incomplete`() {
        val cut = ZenProtocol.parse(
            """{"choices":[{"message":{"content":"обрыв"},"finish_reason":"length"}]}""",
            "big-pickle",
        )
        assertTrue(!cut.complete)

        val anth = ZenProtocol.parse("""{"content":[],"stop_reason":"max_tokens"}""", "claude-opus-5")
        assertTrue(!anth.complete)
    }

    @Test
    fun `request body matches the endpoint`() {
        val chat = ZenProtocol.requestBody("big-pickle", "вопрос", "система", 100)
        assertNotNull(chat["messages"])
        assertEquals(100, (chat["max_tokens"] as kotlinx.serialization.json.JsonPrimitive).content.toInt())

