            return Regex("[\\u0400-\\u04FF]{3,}").containsMatchIn(row)
        }
        "en" -> {
            val lat = row.count { it in 'a'..'z' || it in 'A'..'Z' }
            if (lat.toFloat() / letters < 0.6f) return false
