import kotlinx.coroutines.withContext
import mihon.domain.ocr.service.OcrPreferences
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get

/**
 * Вкладка «AI»: один слой — токен и запуск. После запуска в этой же вкладке
 * открывается сайт-хаб npm-hub (дашборд / терминал / файлы / git / инструменты)
 * с GitHub-ранера, где живут CLI-агенты. Агент НЕ форсится при запуске —
 * пользователь сам выбирает и устанавливает его внутри хаба (как в оригинале).
 */
data object AiChatTab : Tab {

    override val options: TabOptions
        @Composable
        get() = TabOptions(
            index = 9u,
            title = "AI",
            icon = rememberVectorPainter(Icons.Outlined.SmartToy),
        )

    // Запуск переживает уход со вкладки и сворачивание приложения
    private val chatScope = kotlinx.coroutines.CoroutineScope(
        kotlinx.coroutines.SupervisorJob() + Dispatchers.IO,
    )
    private val hubStatusFlow = MutableStateFlow("")
    private val hubStartingFlow = MutableStateFlow(false)
    // Fix 5: активная сессия живёт на уровне ОБЪЕКТА, а не в remember —
    // при переключении вкладки (и обратно) WebView не «теряется».
    private val hubSessionFlow = MutableStateFlow<RunnerLlm.Session?>(null)

    private fun rememberSession(s: RunnerLlm.Session) {
        hubSessionFlow.value = s
    }

    @Composable
    override fun Content() {
        val context = LocalContext.current
        val prefs = remember { Injekt.get<OcrPreferences>() }
        val pat by prefs.githubPat().changes().collectAsState(initial = prefs.githubPat().get())
        val starting by hubStartingFlow.collectAsState()
        val status by hubStatusFlow.collectAsState()
        val session by hubSessionFlow.collectAsState()
        var sessions by remember {
            mutableStateOf(runCatching { RunnerLlm.listSessions(context) }.getOrDefault(emptyList()))
        }

        val openSession = session
        if (openSession != null) {
            HubWebView(
                session = openSession,
                onClose = { hubSessionFlow.value = null },
            )
        } else {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .statusBarsPadding()
                    .imePadding()
                    .verticalScroll(rememberScrollState())
                    .padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp),
            ) {
                Text("OpenCode-агент", style = MaterialTheme.typography.titleMedium)
                Text(
                    "Запускает сайт-хаб (npm-hub) на GitHub-ранере: дашборд, терминал, " +
                        "файлы, git, инструменты. Нужного CLI-агента (opencode, DeepSeek, UTIM, " +
                        "AI Shell и др.) вы сами выбираете и устанавливаете прямо внутри хаба. " +
                        "Ранер работает вашим PAT аккаунта, поэтому видит и меняет ВСЕ репозитории " +
                        "аккаунта. Нужен PAT с правом actions:write.",
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                )
                OutlinedTextField(
                    value = pat,
                    onValueChange = { token ->
                        // Пробелы по краям ломают GitHub Auth: token = " ghp_…x "
                    // считается невалидным и старт сессии падает с 401.
                        prefs.githubPat().set(token.trim())
                    },
                    label = { Text("GitHub PAT") },
                    modifier = Modifier.fillMaxWidth(),
                    maxLines = 1,
                )
                var elapsed by remember { mutableStateOf(0L) }
                LaunchedEffect(starting) {
                    elapsed = 0
                    while (starting) {
                        delay(1000)
                        elapsed++
                    }
                }
                FilledTonalButton(
                    enabled = !starting && pat.isNotBlank(),
                    onClick = {
                        val trimmed = pat.trim()
                        val looksLikePat = trimmed.startsWith("ghp_") ||
                            trimmed.startsWith("github_pat_") ||
                            trimmed.startsWith("gho_") ||
                            trimmed.startsWith("ghs_") ||
                            trimmed.startsWith("ghr_")
                        if (!looksLikePat) {
                            hubStatusFlow.value =
                                "❌ Токен не похож на GitHub PAT. Нужен токен, " +
                                "начинающийся на ghp_ / github_pat_ / gho_ (Settings → Developer settings → " +
                                "Personal access tokens). Вставлен Discord- или другой токен?"
                            return@FilledTonalButton
                        }
                        hubStartingFlow.value = true
                        hubStatusFlow.value = "⏳ Запуск хаба npm-hub…"
                        val appCtx = context.applicationContext
                        chatScope.launch {
                            val s = runCatching {
                                RunnerLlm.startOpenCode(
                                    appCtx,
                                    { st -> hubStatusFlow.value = st },
                                    os = "linux",
                                    ui = "mobile",
                                )
                            }.getOrElse {
                                hubStatusFlow.value = "❌ Ошибка запуска: ${it.message ?: it}"
                                null
                            }
                            withContext(Dispatchers.Main) {
                                hubStartingFlow.value = false
                                if (s != null) {
                                    sessions = runCatching { RunnerLlm.listSessions(context) }
                                        .getOrDefault(emptyList())
                                    rememberSession(s)
                                }
                            }
                        }
                    },
                ) { Text(if (starting) "Запускаем…" else "▶ Запустить") }
                if (status.isNotBlank()) {
                    Text(
                        if (starting) "$status • ${elapsed / 60}:${"%02d".format(elapsed % 60)}"
                        else status,
                        style = MaterialTheme.typography.bodySmall,
                    )
                }
                if (sessions.isNotEmpty()) {
                    Text("Сессии:", style = MaterialTheme.typography.bodySmall)
                    sessions.forEach { s ->
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                        ) {
                            Text(
                                "${s.model} • ${s.messages.size} сообщ. • ${s.os}",
                                style = MaterialTheme.typography.bodySmall,
                                modifier = Modifier.weight(1f),
                            )
                            if (s.terminalUrl != null || s.url != null) {
                                FilterChip(
                                    selected = false,
                                    onClick = { rememberSession(s) },
                                    label = { Text("Открыть") },
                                )
                            }
                            FilterChip(
                                selected = false,
                                onClick = {
                                    runCatching {
                                        RunnerLlm.deleteSession(context, s)
                                        sessions = RunnerLlm.listSessions(context)
                                    }
                                },
                                label = { Text("✕") },
                            )
                        }
                    }
                }
            }
        }
    }

    /** Сайт-хаб npm-hub в той же вкладке: loading-экран вместо чёрного + ошибки. */
    @Composable
    @android.annotation.SuppressLint("SetJavaScriptEnabled")
    private fun HubWebView(
        session: RunnerLlm.Session,
        onClose: () -> Unit,
    ) {
        val context = LocalContext.current
        val url = session.terminalUrl ?: session.url.orEmpty()
        var loading by remember(session.id) { mutableStateOf(true) }
        var error by remember(session.id) { mutableStateOf<String?>(null) }
        val webView = remember(session.id, url) {
            runCatching {
                WebView(context).apply {
                    // На чёрном фоне «протухающий» туннель выглядел как мёртвый экран.
                    setBackgroundColor(android.graphics.Color.WHITE)
                    isFocusable = true
                    isFocusableInTouchMode = true
                    settings.javaScriptEnabled = true
                    settings.domStorageEnabled = true
                    settings.loadWithOverviewMode = false
                    settings.useWideViewPort = false
                    settings.builtInZoomControls = false
                    settings.displayZoomControls = false
                    settings.mixedContentMode = android.webkit.WebSettings.MIXED_CONTENT_ALWAYS_ALLOW
                    webViewClient = object : WebViewClient() {
                        override fun onReceivedHttpAuthRequest(
                            view: WebView?,
                            handler: HttpAuthHandler,
                            host: String?,
                            realm: String?,
                        ) {
                            runCatching { handler.proceed("yomikai", session.apiKey.orEmpty()) }
                        }

                        override fun onPageFinished(view: WebView?, url: String?) {
                            loading = false
                            error = null
                            view?.requestFocus()
                        }

                        override fun onReceivedError(
                            view: WebView?,
                            errorCode: Int,
                            description: String?,
                            failingUrl: String?,
                        ) {
                            loading = false
                            error = "Ошибка загрузки ($errorCode): $description"
                        }

                        override fun onReceivedHttpError(
                            view: WebView?,
                            request: android.webkit.WebResourceRequest?,
                            errorResponse: android.webkit.WebResourceResponse?,
                        ) {
                            loading = false
                            val code = errorResponse?.statusCode ?: 0
                            val mime = errorResponse?.mimeType.orEmpty()
                            // Discord api error format leaked through a proxy/token:
                            // {"success":false,"result":null,"errors":[{"code":10005,...}]}
                            val body = runCatching {
                                errorResponse?.data?.bufferedReader()?.use { it.readText() }.orEmpty()
                            }.getOrDefault("").take(300)
                            if (code == 405 || body.contains("method not allowed", ignoreCase = true)) {
                                error = "Ранер ответил $code (Method Not Allowed). Скорее всего в поле " +
                                    "GitHub PAT вставлен НЕ-GitHub токен (например Discord). Возьмите " +
                                    "настоящий GitHub PAT (ghp_/github_pat_). Ответ: $body"
                            } else {
                                error = "HTTP $code на сайте ранера" +
                                    body.takeIf { it.isNotBlank() }?.let { "\n$it" }.orEmpty()
                            }
                        }
                    }
                    if (url.isNotBlank()) loadUrl(url)
                }
            }.getOrElse {
                error = "WebView не создался: ${it.message ?: it}"
                null
            }
        }
        DisposableEffect(webView) {
            onDispose {
                runCatching {
                    (webView?.parent as? android.view.ViewGroup)?.removeView(webView)
                    webView?.stopLoading()
                    webView?.destroy()
                }
            }
        }

        Column(modifier = Modifier.fillMaxSize().statusBarsPadding()) {
            Row(
                modifier = Modifier.fillMaxWidth().padding(horizontal = 12.dp, vertical = 4.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                Text(
                    "npm-hub • ${session.os}" +
                        (if (loading) " • подключение…" else " • сайт"),
                    style = MaterialTheme.typography.bodySmall,
                    modifier = Modifier.weight(1f),
                )
                IconButton(onClick = {
                    loading = true
                    error = null
                    runCatching { webView?.reload() }
                }) {
                    Icon(Icons.Outlined.Refresh, contentDescription = "Перезагрузить")
                }
                TextButton(onClick = onClose) { Text("Закрыть") }
            }
            if (webView != null && error == null) {
                AndroidView(
                    factory = { webView },
                    modifier = Modifier.fillMaxSize(),
                )
            } else {
                Column(
                    modifier = Modifier.fillMaxSize().padding(24.dp),
                    verticalArrangement = Arrangement.Center,
                    horizontalAlignment = Alignment.CenterHorizontally,
                ) {
                    Text(
                        error ?: "Сайт хаба недоступен. Проверьте, что ранер ещё жив.",
                        style = MaterialTheme.typography.bodyMedium,
                    )
                    FilledTonalButton(
                        onClick = { error = null; loading = true; runCatching { webView?.reload() } },
                    ) { Text("Попробовать снова") }
                    TextButton(onClick = onClose) { Text("Закрыть и к запуску") }
                }
            }
        }
    }
}

package eu.kanade.tachiyomi.data.books

import android.content.Context
import android.graphics.BitmapFactory
import android.provider.OpenableColumns
import com.hippo.unifile.UniFile
import java.io.File
import java.io.FileOutputStream
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get

/**
 * Хранилище локальных электронных книг.
 *
 * Книги лежат в подкаталоге `books/` основного хранилища приложения.
 * Поддерживаются: PDF, EPUB, FB2, DOCX, HTML, TXT и другие текстовые форматы.
 *
 * Прогресс чтения хранится в SharedPreferences, метаданные и обложки — в кэше.
 */
object BooksStore {

    data class Snapshot(
        val chapter: Int = 0,
        val sentence: Int = 0,
        val percent: Int = 0,
    )

    /**
     * Результат добавления книги.
     */
    sealed class ImportResult {
        data class Success(val book: UniFile) : ImportResult()
        data class Failure(val reason: String) : ImportResult()
    }

    private const val PROGRESS_PREFS = "yomikai_books_progress"
    private const val METADATA_PREFS = "yomikai_books_metadata"
    private const val COVER_DIR = "book_covers"

    private fun storageManager(): tachiyomi.domain.storage.service.StorageManager =
        Injekt.get()

    fun booksDirectory(context: Context): UniFile? {
        val primary = storageManager().getBooksDirectory()
        if (primary != null && primary.exists()) return primary
        val folder = File(context.filesDir, "books")
        if (!folder.exists()) folder.mkdirs()
        return UniFile.fromFile(folder)
    }

    /** Список книг (исключая скрытые файлы), отсортированные по имени. */
    fun listBooks(context: Context): List<UniFile> {
        return booksDirectory(context)?.listFiles()
            ?.filter { !it.name.orEmpty().startsWith('.') }
            ?.sortedBy { it.name.orEmpty().lowercase() }
            .orEmpty()
            .toList()
    }

    /**
     * Копирует выбранный пользователем файл (SAF URI) в каталог книг.
     */
    fun importBook(context: Context, uri: android.net.Uri): ImportResult {
        val dir = booksDirectory(context) ?: return ImportResult.Failure("Нет каталога для книг")
        val input = try {
            context.contentResolver.openInputStream(uri)
        } catch (e: Exception) {
            return ImportResult.Failure("Не удалось открыть файл: ${e.message}")
        } ?: return ImportResult.Failure("Файл открыт, но пуст или недоступен")

        return input.use { stream ->
            try {
                val name = displayName(context, uri)
                    ?.takeIf { it.isNotBlank() }
                    ?: "book_${System.currentTimeMillis()}"
                val safeName = name.replace(Regex("[/\\\\:<>|?*\"]"), "_")

                var candidate = safeName
                var attempt = 0
                while (dir.findFile(candidate)?.exists() == true) {
                    attempt++
                    val dot = safeName.lastIndexOf('.')
                    candidate = if (dot > 0) {
                        safeName.substring(0, dot) + "($attempt)" + safeName.substring(dot)
                    } else {
                        "$safeName($attempt)"
                    }
                }
                val target = dir.createFile(candidate)
                    ?: return@use ImportResult.Failure(
                        "Не удалось создать файл «$candidate» в хранилище",
                    )
                val out = try {
                    target.openOutputStream()
                } catch (e: Exception) {
                    target.delete()
                    return@use ImportResult.Failure("Нет прав на запись: ${e.message}")
                } ?: run {
                    target.delete()
                    return@use ImportResult.Failure("Не удалось открыть файл для записи")
                }
                out.use { targetOut ->
                    stream.copyTo(targetOut, 64 * 1024)
                }
                val finalFile = dir.findFile(candidate)
                if (finalFile?.exists() == true) {
                    ImportResult.Success(finalFile)
                } else {
                    ImportResult.Failure("Файл не появился после добавления — проверьте хранилище")
                }
            } catch (e: Exception) {
                ImportResult.Failure("Ошибка добавления: ${e.message ?: e.javaClass.simpleName}")
            }
        }
    }

    fun deleteBook(book: UniFile): Boolean {
        return book.delete()
    }

    /** Добавляет книгу из готового массива байт (например, скачанной по URL). */
    fun importBytes(context: Context, fileName: String, content: ByteArray): ImportResult {
        val dir = booksDirectory(context) ?: return ImportResult.Failure("Нет каталога для книг")
        try {
            val safeName = fileName
                .substringAfterLast('/')
                .replace(Regex("[/\\\\:<>|?*\"]"), "_")
                .ifBlank { "book_${System.currentTimeMillis()}" }
            var candidate = safeName
            var attempt = 0
            while (dir.findFile(candidate)?.exists() == true) {
                attempt++
                val dot = candidate.lastIndexOf('.')
                candidate = if (dot > 0) {
                    candidate.substring(0, dot) + "($attempt)" + candidate.substring(dot)
                } else {
                    "$candidate($attempt)"
                }
            }
            val target = dir.createFile(candidate)
                ?: return ImportResult.Failure("Не удалось создать файл «$candidate»")
            val out = target.openOutputStream()
                ?: return ImportResult.Failure("Не удалось открыть файл для записи")
            out.use { it.write(content) }
            return ImportResult.Success(target)
        } catch (e: Exception) {
            return ImportResult.Failure("Ошибка добавления: ${e.message ?: e.javaClass.simpleName}")
        }
    }

    // ---------- Прогресс чтения ----------

    fun save(context: Context, book: UniFile, snapshot: Snapshot) {
        context.getSharedPreferences(PROGRESS_PREFS, Context.MODE_PRIVATE)
            .edit()
            .putString(book.uri.toString(), "${snapshot.chapter}|${snapshot.sentence}|${snapshot.percent}")
            .apply()
    }

    fun clear(context: Context, book: UniFile) {
        context.getSharedPreferences(PROGRESS_PREFS, Context.MODE_PRIVATE)
            .edit()
            .remove(book.uri.toString())
            .apply()
        // Также очищаем кэш метаданных и обложки
        clearMetadata(context, book)
        clearCover(context, book)
    }

    fun load(context: Context, book: UniFile): Snapshot {
        val raw = context.getSharedPreferences(PROGRESS_PREFS, Context.MODE_PRIVATE)
            .getString(book.uri.toString(), null)
            ?: return Snapshot()
        val parts = raw.split('|')
        if (parts.size != 3) return Snapshot()
        return Snapshot(
            chapter = parts[0].toIntOrNull()?.coerceAtLeast(0) ?: 0,
            sentence = parts[1].toIntOrNull()?.coerceAtLeast(0) ?: 0,
            percent = parts[2].toIntOrNull()?.coerceIn(0, 100) ?: 0,
        )
    }

    // ---------- Метаданные ----------

    /**
     * Сохраняет метаданные книги в SharedPreferences.
     * Ключ = URI книги, значение = JSON строка "title|author|description|language|publisher|year".
     */
    fun saveMetadata(context: Context, book: UniFile, metadata: BookParser.BookMetadata) {
        val key = book.uri.toString()
        val value = listOf(
            metadata.title,
            metadata.author.orEmpty(),
            metadata.description.orEmpty(),
            metadata.language.orEmpty(),
            metadata.publisher.orEmpty(),
            metadata.year?.toString().orEmpty(),
            metadata.genre?.joinToString(",").orEmpty(),
        ).joinToString("|||")
        context.getSharedPreferences(METADATA_PREFS, Context.MODE_PRIVATE)
            .edit()
            .putString(key, value)
            .apply()
    }

    /**
     * Загружает сохранённые метаданные книги. Если нет — извлекает из файла.
     */
    fun loadMetadata(context: Context, book: UniFile): BookParser.BookMetadata {
        val key = book.uri.toString()
        val raw = context.getSharedPreferences(METADATA_PREFS, Context.MODE_PRIVATE)
            .getString(key, null)
        if (raw != null) {
            val parts = raw.split("|||")
            if (parts.size >= 7) {
                return BookParser.BookMetadata(
                    title = parts[0].ifBlank { book.name.orEmpty().substringBeforeLast('.') },
                    author = parts[1].ifBlank { null },
                    description = parts[2].ifBlank { null },
                    language = parts[3].ifBlank { null },
                    publisher = parts[4].ifBlank { null },
                    year = parts[5].toIntOrNull(),
                    genre = parts[6].ifBlank { null }?.split(","),
                )
            }
        }
        // Извлекаем из файла и кэшируем
        return try {
            val metadata = BookParser.extractMetadata(book)
            saveMetadata(context, book, metadata)
            metadata
        } catch (e: Exception) {
            BookParser.BookMetadata(title = book.name.orEmpty().substringBeforeLast('.'))
        }
    }

    private fun clearMetadata(context: Context, book: UniFile) {
        context.getSharedPreferences(METADATA_PREFS, Context.MODE_PRIVATE)
            .edit()
            .remove(book.uri.toString())
            .apply()
    }

    // ---------- Обложки ----------

    private fun coversDir(context: Context): File {
        val dir = File(context.filesDir, COVER_DIR)
        if (!dir.exists()) dir.mkdirs()
        return dir
    }

    private fun coverFileName(book: UniFile): String {
        return book.uri.toString()
            .replace(Regex("[^a-zA-Z0-9]"), "_")
            .take(128) + ".png"
    }

    /**
     * Загружает обложку книги. Если нет в кэше — извлекает из файла.
     */
    fun loadCover(context: Context, book: UniFile): android.graphics.Bitmap? {
        val cacheFile = File(coversDir(context), coverFileName(book))
        if (cacheFile.exists()) {
            val bitmap = BitmapFactory.decodeFile(cacheFile.absolutePath)
            if (bitmap != null) return bitmap
            cacheFile.delete()
        }
        // Извлекаем и кэшируем
        return try {
            val coverBytes = BookParser.extractCover(context, book) ?: return null
            val bitmap = BitmapFactory.decodeByteArray(coverBytes, 0, coverBytes.size) ?: return null
            FileOutputStream(cacheFile).use { it.write(coverBytes) }
            bitmap
        } catch (e: Exception) {
            null
        }
    }

    /**
     * Возвращает путь к обложке (или null).
     *
     * Библиотека читает только этот путь, поэтому обложка обязана появиться
     * здесь. Раньше метод лишь смотрел в кэш: пока кто-то не вызвал
     * [loadCover], каждая книга показывалась заведомо «без обложки», хотя
     * извлечение было бы успешным. Теперь при отсутствии кэша обложка
     * извлекается и сохраняется на лету.
     */
    fun coverPath(context: Context, book: UniFile): String? {
        val cacheFile = File(coversDir(context), coverFileName(book))
        if (cacheFile.exists()) return cacheFile.absolutePath
        return try {
            val coverBytes = BookParser.extractCover(context, book) ?: return null
            FileOutputStream(cacheFile).use { it.write(coverBytes) }
            cacheFile.absolutePath
        } catch (e: Exception) {
            null
        }
    }

    private fun clearCover(context: Context, book: UniFile) {
        File(coversDir(context), coverFileName(book)).delete()
    }

    /** Сохраняет обложку (PNG/JPEG байты) в кэш, чтобы её можно было отдать по пути. */
    fun saveCover(context: Context, book: UniFile, bytes: ByteArray) {
        try {
            FileOutputStream(File(coversDir(context), coverFileName(book))).use { it.write(bytes) }
        } catch (e: Exception) {
            // кэш не критичен
        }
    }

    private fun displayName(context: Context, uri: android.net.Uri): String? {
        context.contentResolver.query(uri, null, null, null, null)?.use { cursor ->
            if (cursor.moveToFirst()) {
                val idx = cursor.getColumnIndex(OpenableColumns.DISPLAY_NAME)
                if (idx >= 0) return cursor.getString(idx)
            }
        }
        return uri.lastPathSegment
    }
}

package eu.kanade.tachiyomi.data.books

import android.graphics.Bitmap
import eu.kanade.tachiyomi.util.ocr.toOcrImage
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import logcat.LogPriority
import mihon.domain.ocr.interactor.OcrProcessor
import tachiyomi.core.common.util.system.logcat
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get

/**
 * Распознавание текста страниц для книг (сканированные PDF, картинки внутри
 * EPUB). Использует штатный OCR-конвейер приложения (движок книг — CYRILLIC,
 * без сети и без моделей). Все ошибки обёрнуты в runCatching — OCR никогда
 * не роняет читалку.
 */
object BookOcr {

    private val processor: OcrProcessor by lazy { Injekt.get<OcrProcessor>() }

    /** Распознаёт текст на битмапе. null при любой ошибке (без исключений). */
    suspend fun recognize(bitmap: Bitmap): String? = withContext(Dispatchers.IO) {
        runCatching {
            val needsCopy = bitmap.config != Bitmap.Config.ARGB_8888
            val bmp = if (needsCopy) bitmap.copy(Bitmap.Config.ARGB_8888, false) ?: bitmap else bitmap
            val text = processor.getText(bmp.toOcrImage())
            if (needsCopy && bmp !== bitmap) bmp.recycle()
            text.trim()
        }.onFailure { e ->
            logcat(LogPriority.WARN, e) { "BookOcr: recognition failed" }
        }.getOrNull()?.takeIf { it.isNotBlank() }
    }
}

package eu.kanade.tachiyomi.data.tts

import android.content.Context
import android.speech.tts.TextToSpeech
import mihon.domain.ocr.service.OcrPreferences
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get

/**
 * Продвинутый резолвер голосов: 1 / 2 / 3 голоса.
 *
 * Запрос пользователя:
 *  - 1 голос — один нарратор (выбор муж/жен) озвучивает всё
 *  - 2 голоса — мужской и женский (локальный или онлайн) по полу реплики
 *  - 3 голоса — муж + жен + нарратор (отдельный выбор)
 *
 *Каждый из трёх слотов имеет свой движок:
 *  - `pref_voice_male_engine`  → male
 *  - `pref_voice_female_engine`→ female
 *  - `pref_voice_narrator_engine` → narrator
 *и свой голос внутри движка (`pref_voice_male`, `pref_voice_female`, `pref_voice_name` для нарратора).
 *
 * Логика [resolve] применяется в [TtsSpeaker.speakAs] и [AutoReadEngine].
 */
object VoiceModeResolver {

    enum class Mode(val id: String, val title: String, val desc: String) {
        SINGLE("single", "Один голос", "Весь текст — голосом нарратора"),
        DUAL("dual", "Два голоса", "Мужские реплики — мужским, женские — женским"),
        TRIPLE("triple", "Три голоса", "Муж + Жен + Нарратор (описания, ремарки)"),
        /** Много голосов: свой голос каждому персонажу одного пола в сцене. */
        MULTI("multi", "Много голосов", "Отдельный голос каждому персонажу одного пола"),
        ;

        companion object {
            fun fromId(id: String?): Mode = entries.firstOrNull { it.id == id } ?: DUAL
        }
    }

    data class ResolvedVoice(
        val gender: String, // male | female | narrator
        val engine: String, // system_tts | google_web | remote_tts | eleven_api
        val voiceName: String,
        val isLocal: Boolean,
        val isOnline: Boolean,
    )

    private fun prefs(): OcrPreferences = Injekt.get()

    fun currentMode(): Mode = Mode.fromId(prefs().voiceMode().get())

    fun narratorGender(): String = prefs().narratorGender().get().lowercase().let {
        when (it) {
            "male", "female" -> it
            else -> "female" // auto → female по умолчанию
        }
    }

    /**
     * Выбрать голос для реплики с учётом режима и пола, определённого
     * морфологией/AI (female/male/null).
     *
     * @param detectedGender пол реплики от RuMorph/AI: "female"|"male"|null
     * @param isNarration был ли текст помечен как нарратив (без кавычек, описания)
     */
    fun resolve(
        detectedGender: String?,
        isNarration: Boolean = false,
        speakerSlot: Int = 0,
    ): ResolvedVoice {
        val mode = currentMode()
        val p = prefs()

        return when (mode) {
            Mode.SINGLE -> {
                val g = narratorGender()
                val engine = p.voiceNarratorEngine().get().ifBlank { p.voiceEngine().get() }
                val name = when (g) {
                    "male" -> p.voiceMale().get().ifBlank { p.voiceName().get() }
                    else -> p.voiceFemale().get().ifBlank { p.voiceName().get() }
                }
ResolvedVoice(
                    gender = g,
                    engine = engine,
                    voiceName = name,
                    isLocal = engine == TtsSpeaker.ENGINE_SYSTEM || engine == TtsSpeaker.ENGINE_REMOTE,
                    isOnline = engine == TtsSpeaker.ENGINE_GOOGLE_WEB || engine == TtsSpeaker.ENGINE_EDGE_TTS,
                )
            }
            Mode.DUAL -> {
                val g = detectedGender ?: narratorGender()
                val isMale = g == "male"
                val engine = if (isMale) p.voiceMaleEngine().get() else p.voiceFemaleEngine().get()
                val fallbackEngine = p.voiceEngine().get()
                val effEngine = engine.ifBlank { fallbackEngine }
                val name = if (isMale) p.voiceMale().get() else p.voiceFemale().get()
                ResolvedVoice(
                    gender = g,
                    engine = effEngine.ifBlank { TtsSpeaker.ENGINE_SYSTEM },
                    voiceName = name,
                    isLocal = effEngine == TtsSpeaker.ENGINE_SYSTEM || effEngine == TtsSpeaker.ENGINE_REMOTE,
                    isOnline = effEngine == TtsSpeaker.ENGINE_GOOGLE_WEB || effEngine == TtsSpeaker.ENGINE_EDGE_TTS,
                )
            }
            Mode.TRIPLE -> {
                if (isNarration) {
                    val g = narratorGender()
                    val engine = p.voiceNarratorEngine().get().ifBlank { p.voiceEngine().get() }
                    val name = when (g) {
                        "male" -> p.voiceMale().get().ifBlank { p.voiceName().get() }
                        else -> p.voiceFemale().get().ifBlank { p.voiceName().get() }
                    }
                    ResolvedVoice(g, engine.ifBlank { TtsSpeaker.ENGINE_SYSTEM }, name, true, false)
                } else {
                    val g = detectedGender ?: "female"
                    val isMale = g == "male"
                    val engine = if (isMale) p.voiceMaleEngine().get() else p.voiceFemaleEngine().get()
                    val name = if (isMale) p.voiceMale().get() else p.voiceFemale().get()
                    ResolvedVoice(g, engine.ifBlank { TtsSpeaker.ENGINE_SYSTEM }, name, true, false)
                }
            }
            // Много голосов: по полу, как DUAL; отдельные слоты персонажам
            // назначаются в AutoReadEngine (speakerSlot), здесь voice тот же.
            Mode.MULTI -> {
                val g = detectedGender ?: narratorGender()
                val isMale = g == "male"
                val engine = if (isMale) p.voiceMaleEngine().get() else p.voiceFemaleEngine().get()
                val fallbackEngine = p.voiceEngine().get()
                val effEngine = engine.ifBlank { fallbackEngine }
                val name = if (isMale) p.voiceMale().get() else p.voiceFemale().get()
                ResolvedVoice(
                    gender = g,
                    engine = effEngine.ifBlank { TtsSpeaker.ENGINE_SYSTEM },
                    voiceName = name,
                    isLocal = effEngine == TtsSpeaker.ENGINE_SYSTEM || effEngine == TtsSpeaker.ENGINE_REMOTE,
                    isOnline = effEngine == TtsSpeaker.ENGINE_GOOGLE_WEB || effEngine == TtsSpeaker.ENGINE_EDGE_TTS,
                )
            }
        }
    }

    fun describeCurrent(): String {
        val mode = currentMode()
        val p = prefs()
        return when (mode) {
            Mode.SINGLE -> "Один голос: нарратор ${narratorGender()} (${p.voiceNarratorEngine().get().ifBlank { p.voiceEngine().get() }})"
            Mode.DUAL -> "Два голоса: муж (${p.voiceMaleEngine().get().ifBlank { "system_tts" }}) + жен (${p.voiceFemaleEngine().get().ifBlank { "system_tts" }})"
            Mode.TRIPLE -> "Три голоса: муж (${p.voiceMaleEngine().get()}) + жен (${p.voiceFemaleEngine().get()}) + нарратор ${narratorGender()} (${p.voiceNarratorEngine().get()})"
            Mode.MULTI -> "Много голосов: отдельный голос каждому персонажу одного пола"
        }
    }

    /**
     * Применить resolved-голос к TextToSpeech: setVoice + rate/pitch от VoicePreset.
     */
    fun applyToTts(
        tts: TextToSpeech?,
        resolved: ResolvedVoice,
        rate: Float,
        pitch: Float,
    ) {
        if (tts == null) return
        val kind = when (resolved.gender) {
            "male" -> VoiceKind.MALE
            "female" -> VoiceKind.FEMALE
            else -> VoiceKind.OTHER
        }
        val voice = VoiceHelper.pickFor(tts, kind, resolved.voiceName.takeIf { it.isNotBlank() }, "ru", null)
        if (voice != null) {
            runCatching { tts.voice = voice }
        }
        tts.setSpeechRate(rate)
        tts.setPitch(pitch)
    }
}

package eu.kanade.tachiyomi.data.tts

import mihon.domain.ocr.service.OcrPreferences

/**
 * Роль говорящего (персонаж) для озвучки.
 *
 * Полноценный словарь поверх прежних трёх слотов ♀/♂/🎙: роль связывает имя
 * или метки [markers] с голосом, полом, возрастом и модификаторами
 * питча/темпа. Имя приходит из разметки `{имя:Аки}`, пол — из `{ж}/{м}` или
 * пресета пользователя.
 *
 * Правила подбора, по убыванию приоритета:
 *  1. имя говорящего совпало с меткой роли (без учёта регистра, подстрока);
 *  2. имя совпало с [name];
 *  3. явный пол (male/female) совпал с [gender] роли (клавиши ♀/♂/🎙 и
 *     ручной режим);
 *  4. пол «auto» — первая роль запасного совпадения только по имени [name]
 *     даже без меток не выбирается (риск ложного срабатывания).
 *
 * Все модификаторы перемножаются с пресетами [VoicePreset], поэтому роль
 * «Старик» звучит ниже/медленнее без ручной звукорежиссуры.
 */
data class VoiceRole(
    val id: String,
    val name: String,
    val gender: String = "auto", // auto | male | female | neutral
    val age: String = "adult", // VoicePreset.Age.id
    val voice: String = "", // «пакет::имя», пусто = подбор по полу/возрасту
    val pitch: Float = 1.0f,
    val rate: Float = 1.0f,
    val markers: List<String> = emptyList(),
) {

    /** Совпадает ли роль с именем говорящего (`{имя:Аки}`). */
    fun matchesName(speakerName: String?): Boolean {
        if (speakerName.isNullOrBlank()) return false
        val name = speakerName.trim().lowercase()
        if (this.name.lowercase() == name) return true
        return markers.any { marker ->
            val m = marker.lowercase()
            m == name || name.contains(m) || m.contains(name)
        }
    }

    /** Совпадает ли роль с явным полом реплики. */
    fun matchesGender(roleGender: String?): Boolean {
        if (roleGender.isNullOrBlank()) return false
        if (gender == "auto") return false
        return roleGender.equals(gender, ignoreCase = true) || roleGender == "narrator"
    }

    companion object {
        const val GENDER_AUTO = "auto"
        const val GENDER_MALE = "male"
        const val GENDER_FEMALE = "female"
        const val GENDER_NEUTRAL = "neutral"
    }
}

/**
 * Доступ к словарю голосовых ролей: JSON хранится в настройках
 * ([OcrPreferences.voiceRoles]), читается при каждой озвучке — менять роли
 * можно без перезапуска приложения.
 */
object VoiceRoleDictionary {

    /**
     * Разбор строки JSON-массива ролей. Не зависит от org.json (в юнит-тестах
     * app-модуля org.json не замокан и бросает), поэтому полностью ручной.
     */
    fun parse(json: String): List<VoiceRole> {
        val trimmed = json.trim()
        if (trimmed.isEmpty()) return emptyList()
        return VoiceJson.parseObjects(trimmed).mapNotNull { obj ->
            val name = obj["name"].orEmpty()
            if (name.isBlank()) return@mapNotNull null
            val markers = VoiceJson.parseArrayTokens(obj["markers"].orEmpty())
            VoiceRole(
                id = obj["id"].orEmpty().ifBlank { name },
                name = name,
                gender = obj["gender"].orEmpty().ifBlank { VoiceRole.GENDER_AUTO },
                age = obj["age"].orEmpty().ifBlank { "adult" },
                voice = obj["voice"].orEmpty(),
                pitch = obj["pitch"]?.toFloatOrNull()?.takeIf { it > 0f } ?: 1.0f,
                rate = obj["rate"]?.toFloatOrNull()?.takeIf { it > 0f } ?: 1.0f,
                markers = markers,
            )
        }
    }

    /** Ручная JSON-сериализация массива ролей. */
    fun toJson(roles: List<VoiceRole>): String {
        val sb = StringBuilder("[")
        roles.forEachIndexed { idx, role ->
            if (idx > 0) sb.append(',')
            sb.append('{')
            sb.append("\"id\":\"").append(VoiceJson.jsonEscape(role.id)).append('"')
            sb.append(",\"name\":\"").append(VoiceJson.jsonEscape(role.name)).append('"')
            sb.append(",\"gender\":\"").append(VoiceJson.jsonEscape(role.gender)).append('"')
            sb.append(",\"age\":\"").append(VoiceJson.jsonEscape(role.age)).append('"')
            sb.append(",\"voice\":\"").append(VoiceJson.jsonEscape(role.voice)).append('"')
            sb.append(",\"pitch\":").append(role.pitch)
            sb.append(",\"rate\":").append(role.rate)
            sb.append(",\"markers\":[")
            role.markers.forEachIndexed { mi, marker ->
                if (mi > 0) sb.append(',')
                sb.append('"').append(VoiceJson.jsonEscape(marker)).append('"')
            }
            sb.append("]}")
        }
        sb.append(']')
        return sb.toString()
    }

    fun load(prefs: OcrPreferences): List<VoiceRole> = parse(prefs.voiceRoles().get())

    fun save(prefs: OcrPreferences, roles: List<VoiceRole>) {
        prefs.voiceRoles().set(toJson(roles))
    }

    /**
     * Находит роль для реплики. [speakerName] — из `{имя:…}` (приоритет),
     * [gender] — явный пол (`{ж}/{м}`, кнопки карточки, ручной режим).
     */
    fun resolve(
        roles: List<VoiceRole>,
        speakerName: String?,
        gender: String?,
    ): VoiceRole? {
        val named = roles.filter { it.name.isNotBlank() }
        if (speakerName != null) {
            named.firstOrNull { it.matchesName(speakerName) }?.let { return it }
        }
        if (gender != null && (gender.equals("male", true) || gender.equals("female", true))) {
            named.firstOrNull { it.matchesGender(gender) }?.let { return it }
        }
        return null
    }

    fun resolve(prefs: OcrPreferences, speakerName: String?, gender: String?): VoiceRole? =
        resolve(load(prefs), speakerName, gender)
}

package eu.kanade.tachiyomi.data.ai

import io.kotest.matchers.collections.shouldContainExactly
import io.kotest.matchers.shouldBe
import org.junit.jupiter.api.Test

/**
 * Реестр бэкендов AI-чата.
 *
 * Проверяется декларативная часть и чистая функция статуса: реальные запросы
 * к Zen/OpenRouter, скачивание .task-моделей и сессии ранера требуют Android
 * и сеть, поэтому в юнит-тесты не входят.
 */
class AiBackendsTest {

    private val readyState = AiBackendState(
        networkAvailable = true,
        hasOpenRouterKey = true,
        hasGithubPat = true,
        runnerAllowed = true,
        localModelId = "qwen25_05b",
        localModelInstalled = true,
        localModelSizeMb = 521,
        runnerSessionAlive = true,
    )

    @Test
    fun `registry ids match the values stored in pref_ai_backend`() {
        AiBackends.ALL.map { it.id } shouldContainExactly listOf("online", "local", "runner")
        AiBackends.ALL.map { it.id }.distinct().size shouldBe AiBackends.ALL.size

        AiBackends.byId("online") shouldBe AiBackends.ONLINE
        AiBackends.byId("local") shouldBe AiBackends.LOCAL
        AiBackends.byId("runner") shouldBe AiBackends.RUNNER
        // Пустое или неизвестное значение читается как «онлайн» — ровно так же,
        // как это делала маршрутизация вкладки AI до появления реестра.
        AiBackends.byId("") shouldBe AiBackends.ONLINE
        AiBackends.byId(null) shouldBe AiBackends.ONLINE
        AiBackends.byId("что-то-новое") shouldBe AiBackends.ONLINE
    }

    @Test
    fun `only the local backend works offline`() {
        AiBackends.ALL.filter { it.offline }.map { it.id } shouldContainExactly listOf("local")
        AiBackends.ONLINE.requirements shouldContainExactly listOf(AiRequirement.NETWORK)
        // Ключ OpenRouter — подсказка, а не блокирующее требование: без него
        // AiAssistant сам уходит на Zen.
        AiBackends.ONLINE.optionalRequirements shouldContainExactly listOf(AiRequirement.OPENROUTER_KEY)
        AiBackends.RUNNER.requirements shouldContainExactly listOf(
            AiRequirement.NETWORK,
            AiRequirement.GITHUB_PAT,
            AiRequirement.RUNNER_ALLOWED,
            AiRequirement.RUNNER_SESSION,
        )
        AiBackends.LOCAL.requirements shouldContainExactly listOf(AiRequirement.MODEL_DOWNLOAD)
    }

    @Test
    fun `every backend is available on a fully prepared device`() {
        AiBackends.ALL.forEach { plugin ->
            val status = AiBackends.statusOf(plugin, readyState)
            status.available shouldBe true
            status.missing shouldBe emptyList<AiRequirement>()
            status.detail.isNotBlank() shouldBe true
        }
    }

    @Test
    fun `online reports the missing network and the effective provider`() {
        AiBackends.statusOf(AiBackends.ONLINE, readyState.copy(networkAvailable = false))
            .missing shouldContainExactly listOf(AiRequirement.NETWORK)

        val zen = AiBackends.statusOf(AiBackends.ONLINE, readyState, provider = AiAssistant.PROVIDER_ZEN)
        zen.available shouldBe true
        zen.detail shouldBe "Провайдер: Zen (без ключа)"

        // OpenRouter без ключа не готов: chatFull уйдёт на Zen, но в настройках
        // это должно быть видно как проблема выбранного провайдера.
        val noKey = AiBackends.statusOf(
            AiBackends.ONLINE,
            readyState.copy(hasOpenRouterKey = false),
            provider = AiAssistant.PROVIDER_OPENROUTER,
        )
        noKey.available shouldBe false
        noKey.missing shouldContainExactly listOf(AiRequirement.OPENROUTER_KEY)

        // Ключ есть, но сети нет → только сеть: ключ никуда не делся.
        AiBackends.statusOf(
            AiBackends.ONLINE,
            readyState.copy(networkAvailable = false),
            provider = AiAssistant.PROVIDER_OPENROUTER,
        ).missing shouldContainExactly listOf(AiRequirement.NETWORK)

        // Нет ни сети, ни ключа → оба требования, сеть первой.
        val offline = AiBackends.statusOf(
            AiBackends.ONLINE,
            readyState.copy(networkAvailable = false, hasOpenRouterKey = false),
            provider = AiAssistant.PROVIDER_OPENROUTER,
        )
        offline.available shouldBe false
        offline.missing shouldContainExactly listOf(AiRequirement.NETWORK, AiRequirement.OPENROUTER_KEY)
    }

    @Test
    fun `local reports a missing or unselected model`() {
        AiBackends.statusOf(AiBackends.LOCAL, readyState.copy(localModelInstalled = false))
            .missing shouldContainExactly listOf(AiRequirement.MODEL_DOWNLOAD)
        AiBackends.statusOf(AiBackends.LOCAL, readyState.copy(localModelId = "")).detail shouldBe
            "Модель не выбрана"
        AiBackends.statusOf(AiBackends.LOCAL, readyState).detail shouldBe "qwen25_05b • 521 МБ • установлена"
    }

    @Test
    fun `runner lists every unmet requirement in declaration order`() {
        val bare = AiBackends.statusOf(
            AiBackends.RUNNER,
            readyState.copy(
                networkAvailable = false,
                hasGithubPat = false,
                runnerAllowed = false,
                runnerSessionAlive = false,
            ),
        )
        bare.available shouldBe false
        bare.missing shouldContainExactly listOf(
            AiRequirement.NETWORK,
            AiRequirement.GITHUB_PAT,
            AiRequirement.RUNNER_ALLOWED,
            AiRequirement.RUNNER_SESSION,
        )
        bare.detail shouldBe "Разрешение ранера выключено"

        AiBackends.statusOf(AiBackends.RUNNER, readyState.copy(runnerAllowed = false)).detail shouldBe
            "Разрешение ранера выключено"
        AiBackends.statusOf(AiBackends.RUNNER, readyState.copy(runnerSessionAlive = false)).detail shouldBe
            "Нет живой сессии ранера"
        AiBackends.statusOf(AiBackends.RUNNER, readyState).detail shouldBe "Сессия ранера активна"
    }

    @Test
    fun `unknown backend routes to online and never fails`() {
        // Онлайн-бэкенд готов всегда: сеть и ключи проверяет сам AiAssistant,
        // а при сбое возвращает null, который чат превращает в понятный ответ.
        listOf(null, "", "online", "local-ne-sushchestvuet").forEach { key ->
            val route = AiBackends.route(key, readyState)
            route.backendId shouldBe AiBackends.ONLINE.id
            route.ready shouldBe true
            route.message shouldBe null
        }
    }

    @Test
    fun `unready backends explain themselves instead of returning a dead chat function`() {
        val local = AiBackends.route("local", readyState.copy(localModelInstalled = false))
        local.ready shouldBe false
        local.message shouldBe
            "Локальная модель не готова: скачайте её в ⚙ → Локальные LLM и прогоните «Тест»"

        val noModel = AiBackends.route("local", readyState.copy(localModelId = ""))
        noModel.ready shouldBe false
        noModel.message shouldBe local.message

        val runner = AiBackends.route("runner", readyState.copy(runnerSessionAlive = false))
        runner.ready shouldBe false
        runner.message shouldBe "Нет живой ранер-сессии: запустите её в ⚙ → Полу-онлайн LLM"

        // Готовый бэкенд сообщений не выдаёт.
        AiBackends.route("local", readyState).message shouldBe null
        AiBackends.route("runner", readyState).message shouldBe null
    }
}

package eu.kanade.tachiyomi.data.ai

import eu.kanade.tachiyomi.data.ai.AiHistoryManager.Msg
import io.kotest.matchers.collections.shouldContainExactly
import io.kotest.matchers.shouldBe
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import org.junit.jupiter.api.Test

/**
 * Кнопки-варианты [[...]] из ответа модели: разбор в AiAgent и хранение/чтение
 * в истории AiHistoryManager. Проверяется чистый текст-контракт, без сети и
 * Android: модель пишет формат ``[[Вариант]]``, и приложение обязано
 * превратить его в кнопки и не показывать разметку в тексте ответа.
 */
class AiChoicesTest {

    @Test
    fun `parseChoices extracts up to four options`() {
        AiAgent.parseChoices(
            "Финальный ответ текстом.\n[[Прочитать главу]]\n[[Перевести реплику]]\n" +
                "[[Сменить пресет на манхву]]\n[[Нарисовать лого]]\n[[Лишний вариант]]",
        ) shouldContainExactly
            listOf("Прочитать главу", "Перевести реплику", "Сменить пресет на манхву", "Нарисовать лого")
    }

    @Test
    fun `parseChoices returns empty when there are no options`() {
        AiAgent.parseChoices("Обычный ответ без вариантов.") shouldBe emptyList()
        AiAgent.parseChoices("") shouldBe emptyList()
    }

    @Test
    fun `stripChoices removes the markup but keeps the answer text`() {
        AiAgent.stripChoices("Ответ.\n[[Вариант]]") shouldBe "Ответ."
        AiAgent.stripChoices("[[Один вариант]]") shouldBe ""
    }

    @Test
    fun `choices round-trip through history serialization`() {
        val json = Json { ignoreUnknownKeys = true; encodeDefaults = true }
        val msg = Msg(
            role = "ai",
            text = "Готово.",
            time = 123L,
            choices = listOf("Сделать заметку", "Упаковать workspace"),
        )
        val decoded = json.decodeFromString<List<Msg>>(json.encodeToString(listOf(msg))).first()
        decoded.choices shouldBe listOf("Сделать заметку", "Упаковать workspace")
        decoded.text shouldBe "Готово."
    }

    @Test
    fun `older history without choices field still decodes`() {
        val json = Json { ignoreUnknownKeys = true; encodeDefaults = true }
        val old = """[{"role":"ai","text":"Старый ответ","time":1}]"""
        val decoded = json.decodeFromString<List<Msg>>(old).first()
        decoded.choices shouldBe emptyList()
        decoded.text shouldBe "Старый ответ"
    }
}

