// endregion Склейка строк одной реплики

// region Чистка мусора OCR

companion object {
    private const val HISTORY_LIMIT = 600
    private const val MAX_BUBBLES_PER_FRAME = 40

    /**
     * Максимальная длинная сторона кадра для OCR: минимальное разрешение,
     * при котором текст ещё читается. Детектор движка всё равно масштабирует
     * кадр до ~736px, поэтому уменьшенный заранее кадр ускоряет конвертацию
     * пикселей и онлайн-OCR без потери слов.
     */
    private const val OCR_SCAN_MAX_EDGE = 1600

    /** Качество JPEG скриншотов во вкладку «Скриншоты». */
    private const val JPEG_QUALITY = 78

    /**
     * Онлайн-движки OCR (ответ идёт по сети). Если такой движок вернул
     * очень мало строк — кадр дочитывается локальным разбором баллонов,
     * чтобы AI-пропущенная реплика (напр. крупный текст поверх ватермарки)
     * не терялась. Офлайн-движки (CYRILLIC/MLKIT) и так дают строки с боксами.
     */
    private val ONLINE_MODELS = setOf(
        OcrModel.GLENS,
        OcrModel.ZEN_FREE,
        OcrModel.GOOGLE,
        OcrModel.OPENROUTER,
        OcrModel.OWOCR,
    )

    /**
     * Порог «подозрительно мало»: при меньшем числе осмысленных строк
     * онлайн-результата запускается локальный добор баллонов.
     */
    private const val SUPPLEMENT_BUBBLES_MIN = 3

    /** Возвращает кадр в минимально читаемом разрешении (сам же, если он уже мал). */
    private fun downscaleForScan(src: Bitmap): Bitmap {
        if (src.isRecycled) return src
        val longEdge = maxOf(src.width, src.height)
        if (longEdge <= OCR_SCAN_MAX_EDGE) return src
        val scale = OCR_SCAN_MAX_EDGE.toFloat() / longEdge
        return Bitmap.createScaledBitmap(
            src,
            (src.width * scale).toInt().coerceAtLeast(1),
            (src.height * scale).toInt().coerceAtLeast(1),
            true,
        )
    }

    /** Сжимает кадр в JPEG-байты (для вкладки «Скриншоты»). */
    private fun encodeJpeg(bitmap: Bitmap, quality: Int): ByteArray {
        val out = java.io.ByteArrayOutputStream()
        bitmap.compress(Bitmap.CompressFormat.JPEG, quality, out)
        return out.toByteArray()
    }

    /**
     * Максимальное время OCR одного кадра в авточтении. Локальный движок
     * при первом запуске/загрузке модели, а также онлайн-движок (GLENS /
     * Google) при недоступном сервисе БЕЗ этого жёсткого лимита могли
     * заморозить авточтение навсегда. По таймауту кадр считается пустым.
     */
    internal const val OCR_FRAME_TIMEOUT_MS = 25_000L

    fun ttsTimeoutMs(textLength: Int, speechRate: Float): Long {
        val rate = speechRate.takeIf { it.isFinite() && it > 0f }?.coerceIn(0.5f, 2f) ?: 1f
        return (textLength.coerceAtLeast(0) * 220L / rate).toLong() + 8_000L
    }

    /** Настоящие одно- и двухбуквенные русские слова (союзы/предлоги/междометия). */
    private val RUSSIAN_SINGLE_WORD = setOf("а", "и", "в", "с", "у", "о", "я", "к")
    private val RUSSIAN_SHORT_WORD = setOf(
        "но", "не", "да", "он", "мы", "вы", "ты", "ни", "от", "до", "на",
        "за", "по", "из", "ко", "то", "ли", "же", "бы", "ну", "ах", "ох",
        "ой", "эх", "уж", "ага", "так", "тот", "это", "се", "об", "при", "про",
    )

    /** Одно- или двухбуквенное настоящее русское слово. */
    fun isShortRussianWord(text: String): Boolean {
        val t = text.trim().lowercase()
        return t in RUSSIAN_SINGLE_WORD || t in RUSSIAN_SHORT_WORD
    }

    /**
     * Упорядочивает реплики кадра в читаемый порядок.
     *
     * Раньше реплики сортировались одним ключом: манга — по правому краю
     * (самая правая рамка первой), комикс — по левому, вебтун — по верху.
     * На реальной странице рамки баллонов РАЗНОЙ ширины и высоты (широкий
     * баллон сверху и узкий справа внизу), и одноключевая сортировка
     * читала узкий баллон в центре панели раньше верхнего широкого — «верха
     * пропускает». [ReadingOrderSorter] делит кадр рекурсивным разрезанием:
     *  • горизонтальный разрез — сверху вниз (первично);
     *  • вертикальный разрез — справа налево (манга) / слева направо;
     *  • когда чистого разреза нет (перекрытия вебтуна) — позиционный
     *    фолбэк, где первичен верх, а не правый край.
     * Так верхние реплики всегда читаются раньше нижних в любом вложении.
     */
    fun orderRegions(lines: List<Line>, order: String): List<Line> {
        if (lines.size <= 1) return lines
        val direction = when (order) {
            "ltr" -> tachiyomi.core.common.util.system.ReadingDirection.LTR
            "vertical" -> tachiyomi.core.common.util.system.ReadingDirection.VERTICAL
            else -> tachiyomi.core.common.util.system.ReadingDirection.RTL
        }
        // Рамки хранятся в долях 0..1, а сортировщик работает с целыми
        // Rect: масштабируем на 100000, геометрия и зазоры сохраняются.
        val scale = 100_000
        fun rectOf(line: Line) = line.boundingBox.let { b ->
            // Поля Rect заполняем через свойства, а не через конструктор
            // (left, top, right, bottom): mockable-android jar в юнит-тестах
            // не пишет значения из этого конструктора, и сортировщик видел
            // бы вырожденные рамки (0,0,0,0).
            android.graphics.Rect().apply {
                left = (b.left * scale).toInt()
                top = (b.top * scale).toInt()
                right = (b.right * scale).toInt()
                bottom = (b.bottom * scale).toInt()
            }
        }

        // Манга и комикс читаются по горизонтальным полосам (строкам реплик),
        // а направление работает ВНУТРИ полосы. Без этого сортировщик при
        // отсутствии чистого разреза выходил на фолбэк «сначала top», и бабл,
        // стоящий на пару процентов выше слева, читался раньше правого —

package eu.kanade.tachiyomi.data.ai

import android.content.Context
import android.os.Environment
import logcat.LogPriority
import tachiyomi.core.common.util.system.logcat
import java.io.File
import java.io.FileInputStream
import java.io.FileOutputStream
import java.util.zip.ZipEntry
import java.util.zip.ZipOutputStream

/**
 * Workspace встроенного AI-ассистента: реальная папка на диске, куда
 * ассистент складывает результаты (файлы, картинки, архивы), а пользователь
 * может забрать их в любой момент — файловым менеджером или из UI чата.
 *
 * Расположение: /sdcard/Yomikai/AI (создаётся автоматически). Если внешнее
 * хранилище недоступно — приватная папка приложения (files/ai_workspace).
 *
 * ## Контракт надёжности
 *
 * Ни один публичный метод не бросает исключение наружу. Workspace живёт на
 * общем хранилище, которое пользователь может размонтировать, а права —
 * отозвать в любой момент; кроме того, часть методов вызывается прямо из
 * Compose. Поэтому каждая операция обёрнута в `runCatching`, а неудача
 * возвращается как `null` / `false` / пустой список и логируется. Падение
 * одной операции с файлом не должно уносить приложение.
 */
object AiWorkspace {

    private const val DIR_NAME = "AI"

    /** Ограничение на число записей в списке, чтобы большой workspace не съел память. */
    private const val MAX_LIST_ENTRIES = 5_000

    /**
     * Кэш разрешённого корня. `root()` дёргается из `relPath()` на каждую
     * строку списка файлов, а раньше каждый вызов заново делал `mkdirs()` —
     * то есть дисковый ввод на главном потоке. Корень процесса не меняется,
     * поэтому запоминаем его один раз.
     */
    @Volatile
    private var cachedRoot: File? = null

    fun root(context: Context): File {
        cachedRoot?.let { return it }
        val resolved = runCatching {
            val external = File(Environment.getExternalStorageDirectory(), "Yomikai/$DIR_NAME")
            val dir = if (external.parentFile?.exists() == true || external.mkdirs() || external.exists()) {
                external
            } else {
                File(context.filesDir, "ai_workspace")
            }
            dir.mkdirs()
            File(dir, "images").mkdirs()
            File(dir, "inbox").mkdirs()
            dir.takeIf { it.isDirectory } ?: File(context.filesDir, "ai_workspace").apply { mkdirs() }
        }.getOrElse { e ->
            logcat(LogPriority.WARN, e) { "AiWorkspace root failed, falling back to internal storage" }
            runCatching { File(context.filesDir, "ai_workspace").apply { mkdirs() } }
                .getOrElse { File(context.cacheDir, "ai_workspace").apply { mkdirs() } }
        }
        cachedRoot = resolved
        return resolved
    }

    /**
     * Все файлы workspace (рекурсивно), отсортированы: папки → новые файлы.
     * Пустой список — и когда workspace пуст, и когда хранилище недоступно.
     */
    fun listAll(context: Context): List<File> = runCatching {
        val r = root(context)
        r.walkTopDown()
            .onEnter { dir -> runCatching { dir.canRead() }.getOrDefault(false) }
            .filter { it != r }
            .take(MAX_LIST_ENTRIES)
            .sortedWith(compareBy({ !it.isDirectory }, { -runCatching { it.lastModified() }.getOrDefault(0L) }))
            .toList()
    }.getOrElse { e ->
        logcat(LogPriority.WARN, e) { "AiWorkspace listAll failed" }
        emptyList()
    }

    fun relPath(context: Context, f: File): String = runCatching {
        f.absolutePath.removePrefix(root(context).absolutePath).trimStart('/')
    }.getOrDefault(f.name)

    fun relPathOrNull(context: Context, f: File): String? = runCatching {
        val rootPath = root(context).canonicalPath
        val filePath = f.canonicalPath
        if (filePath.startsWith(rootPath) && filePath != rootPath) {
            filePath.removePrefix(rootPath).trimStart('/')
        } else {
            null
        }
    }.getOrNull()

    /** Безопасное разрешение относительного пути (без выхода из workspace). */
    fun resolve(context: Context, rel: String): File? = runCatching {
        val r = root(context)
        val f = File(r, rel.trim().trimStart('/'))
        if (f.canonicalPath.startsWith(r.canonicalPath)) f else null
    }.getOrElse { e ->
        logcat(LogPriority.WARN, e) { "AiWorkspace resolve failed for '$rel'" }
        null
    }

    /** Сохранить текстовый файл; подпапки в имени создаются автоматически. */
    fun writeText(context: Context, name: String, content: String): File? {
        val f = resolve(context, sanitize(name)) ?: return null
        return runCatching {
            f.parentFile?.mkdirs()
            f.writeText(content)
            f
        }.getOrElse { e ->
            logcat(LogPriority.WARN, e) { "AiWorkspace writeText failed for '$name'" }
            null
        }
    }

    fun newImageFile(context: Context, hint: String): File {
        val safe = sanitize(hint).take(40).ifBlank { "image" }
        return File(File(root(context), "images"), "${safe}_${System.currentTimeMillis() % 100000}.jpg")
    }

    /** Копия вложения пользователя в workspace/inbox; `null`, если запись не удалась. */
    fun importAttachment(context: Context, displayName: String, bytes: ByteArray): File? {
        val f = File(
            File(root(context), "inbox"),
            sanitize(displayName).ifBlank { "file_${System.currentTimeMillis()}" },
        )
        return runCatching {
            f.parentFile?.mkdirs()
            f.writeBytes(bytes)
            f
        }.getOrElse { e ->
            logcat(LogPriority.WARN, e) { "AiWorkspace importAttachment failed for '$displayName'" }
            null
        }
    }

    /**
     * Упаковать весь workspace (кроме прежних архивов) в zip.
     * `null`, если архив собрать не удалось (нет места, хранилище размонтировано).
     */
    fun zipAll(context: Context): File? {
        val r = root(context)
        val out = File(r, "workspace_${System.currentTimeMillis() / 1000}.zip")
        val ok = runCatching {
            // Имена записей обязаны быть уникальны, иначе ZipOutputStream бросает
            // ZipException("duplicate entry") — а файлы в разных папках могут
            // совпадать по имени, если relPath() упал и вернул только имя.
            val used = HashSet<String>()
            ZipOutputStream(FileOutputStream(out)).use { zos ->
                r.walkTopDown()
                    .onEnter { dir -> runCatching { dir.canRead() }.getOrDefault(false) }
                    .filter { it.isFile && it != out && !it.name.endsWith(".zip") }
                    .forEach { f ->
                        val name = AiWorkspacePaths.uniqueEntryName(
                            relPath(context, f).ifBlank { f.name },
                            used,
                        )
                        runCatching {
                            FileInputStream(f).use { fis ->
                                zos.putNextEntry(ZipEntry(name))
                                fis.copyTo(zos)
                                zos.closeEntry()
                            }
                        }.onFailure { e ->
                            logcat(LogPriority.WARN, e) { "AiWorkspace zip skipped '$name'" }
                        }
                    }
            }
            true
        }.getOrElse { e ->
            logcat(LogPriority.WARN, e) { "AiWorkspace zipAll failed" }
            false
        }
        if (!ok) {
            runCatching { out.delete() }
            return null
        }
        return out
    }

    /**
     * Бэкап файла перед правкой (чтобы агент «не сломал» файл): копия в
     * backups/<имя>.<timestamp>. Держим до 5 последних бэкапов на файл.
     */
    fun backup(context: Context, f: File): File? {
        if (!runCatching { f.isFile }.getOrDefault(false)) return null
        val dir = File(root(context), "backups").apply { mkdirs() }
        val stamp = System.currentTimeMillis() / 1000
        val dst = File(dir, "${f.name}.$stamp")
        return runCatching {
            f.copyTo(dst, overwrite = true)
            // Ротация: не больше 5 бэкапов на файл
            dir.listFiles { c -> c.name.startsWith(f.name + ".") }
                ?.sortedByDescending { it.name }
                ?.drop(5)
                ?.forEach { runCatching { it.delete() } }
            dst
        }.getOrElse { e ->
            logcat(LogPriority.WARN, e) { "AiWorkspace backup failed for '${f.name}'" }
            null
        }
    }

    fun delete(context: Context, rel: String): Boolean {
        val f = resolve(context, rel) ?: return false
        return runCatching { f.deleteRecursively() }.getOrElse { e ->
            logcat(LogPriority.WARN, e) { "AiWorkspace delete failed for '$rel'" }
            false
        }
    }

    /** Делегирует чистой реализации, которую покрывают unit-тесты. */
    private fun sanitize(name: String): String = AiWorkspacePaths.sanitize(name)
}

package eu.kanade.tachiyomi.data.tts

import mihon.domain.ocr.model.OcrBoundingBox
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertFalse
import org.junit.jupiter.api.Assertions.assertTrue

/**
 * Юнит-тесты чистки OCR-мусора и порядка чтения для авточтения.
 *
 * Фидбек с устройства: одиночные слова («Я», «но», «И») не читались, а знак
 * «!!» — читался; порядок на манге шёл «лесенкой». Ниже фиксируем исправленное
 * поведение чистыми функциями (без Android), которые гоняет CI.
 */
class AutoReadEngineCleanTest {

    @Test
    fun `russian single-letter words are meaningful`() {
        assertTrue(AutoReadEngine.isMeaningful("Я", "ru"))
        assertTrue(AutoReadEngine.isMeaningful("и", "ru"))
        assertTrue(AutoReadEngine.isMeaningful("но", "ru"))
        assertTrue(AutoReadEngine.isMeaningful("не", "ru"))
    }

    @Test
    fun `punctuation only is not meaningful`() {
        assertFalse(AutoReadEngine.isMeaningful("!!", "ru"))
        assertFalse(AutoReadEngine.isMeaningful("...", "ru"))
        assertFalse(AutoReadEngine.isMeaningful("?", "ru"))
    }

    @Test
    fun `garbage is removed but short words survive`() {
        assertEquals("Я", AutoReadEngine.cleanOcrGarbage("Я", "ru"))
        assertEquals("но", AutoReadEngine.cleanOcrGarbage("но", "ru"))
        assertEquals("", AutoReadEngine.cleanOcrGarbage("!!", "ru"))
        // Строка из одних палок/стрелок — целиком мусор.
        assertEquals("", AutoReadEngine.cleanOcrGarbage("| | > |", "ru"))
        // Осмысленная реплика не кромсается.
        assertEquals("МЕНЯ НА РУЧКИ", AutoReadEngine.cleanOcrGarbage("МЕНЯ НА РУЧКИ", "ru"))
    }

    @Test
    fun `short russian word helper`() {
        assertTrue(AutoReadEngine.isShortRussianWord("Я"))
        assertTrue(AutoReadEngine.isShortRussianWord("но"))
        assertTrue(AutoReadEngine.isShortRussianWord("и"))
        assertFalse(AutoReadEngine.isShortRussianWord("например"))
        assertFalse(AutoReadEngine.isShortRussianWord(""))
    }

    @Test
    fun `orderRegions groups by row and sorts ltr`() {
        val lines = listOf(
            AutoReadEngine.Line("A", OcrBoundingBox(0.1f, 0.05f, 0.4f, 0.20f)),
            AutoReadEngine.Line("B", OcrBoundingBox(0.6f, 0.05f, 0.9f, 0.20f)),
            AutoReadEngine.Line("C", OcrBoundingBox(0.1f, 0.55f, 0.5f, 0.70f)),
        )
        val out = AutoReadEngine.orderRegions(lines, "ltr")
        assertEquals(listOf("A", "B", "C"), out.map { it.text })
    }

    @Test
    fun `orderRegions sorts rtl within row`() {
        val lines = listOf(
            AutoReadEngine.Line("A", OcrBoundingBox(0.1f, 0.05f, 0.4f, 0.20f)),
            AutoReadEngine.Line("B", OcrBoundingBox(0.6f, 0.05f, 0.9f, 0.20f)),
            AutoReadEngine.Line("C", OcrBoundingBox(0.1f, 0.55f, 0.5f, 0.70f)),
        )

package eu.kanade.tachiyomi.data.ai

import android.content.Context
import kotlinx.serialization.Serializable
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import logcat.LogPriority
import tachiyomi.core.common.util.system.logcat
import java.io.File

object BookKnowledge {

    private const val MAX_FACTS = 40
    private const val MAX_NOTES = 60

    private val json = Json { ignoreUnknownKeys = true; encodeDefaults = true }

    @Serializable
    data class Note(
        val time: Long = System.currentTimeMillis(),
        val kind: String = "note",
        val text: String = "",
    )

    @Serializable
    data class Book(
        val mangaId: Long,
        var title: String = "",
        var contentType: String = "",
        var readingOrder: String = "",
        var site: String = "",
        var summary: String = "",
        var advice: MutableList<String> = mutableListOf(),
        var facts: MutableList<String> = mutableListOf(),
        var notes: MutableList<Note> = mutableListOf(),
        var updatedAt: Long = 0L,
    ) {
        val researched: Boolean get() = site.isNotBlank() || summary.isNotBlank() || facts.isNotEmpty()
    }

    fun booksDir(context: Context): File {
        val dir = File(AiWorkspace.root(context), "books")
        dir.mkdirs()
        return dir
    }

    fun file(context: Context, mangaId: Long): File = File(booksDir(context), "$mangaId.json")

    fun load(context: Context, mangaId: Long): Book {
        val f = file(context, mangaId)
        if (!f.exists()) return Book(mangaId = mangaId)
        return runCatching { json.decodeFromString<Book>(f.readText()) }
            .getOrElse { e ->
                logcat(LogPriority.WARN, e) { "BookKnowledge load failed for $mangaId" }
                Book(mangaId = mangaId)
            }
    }

    fun save(context: Context, book: Book) {
        book.updatedAt = System.currentTimeMillis()
        runCatching {
            book.advice = book.advice.takeLast(MAX_FACTS).toMutableList()
            book.facts = book.facts.takeLast(MAX_FACTS).toMutableList()
            book.notes = book.notes.takeLast(MAX_NOTES).toMutableList()
            file(context, book.mangaId).writeText(json.encodeToString(book))
        }.onFailure { e ->
            logcat(LogPriority.WARN, e) { "BookKnowledge save failed for ${book.mangaId}" }
        }
    }

    fun remember(context: Context, mangaId: Long, kind: String, text: String): Boolean {
        if (text.isBlank()) return false
        val book = load(context, mangaId)
        val value = text.trim()
        var stored = false
        when (kind.lowercase()) {
            "site" -> {
                if (book.site != value) {
                    book.site = value
                    stored = true
                }
            }
            "summary" -> {
                if (book.summary != value) {
                    book.summary = value
                    stored = true
                }
            }
            "fact" -> {
                book.facts.add(value)
                stored = true
            }
            "advice", "совет" -> {
                book.advice.add(value)
                stored = true
            }
            else -> {
                book.notes.add(Note(kind = kind.lowercase(), text = value))
                stored = true
            }
        }
        if (stored) save(context, book)
        return stored
    }

    fun renderAdvice(context: Context, mangaId: Long?, limit: Int = 8): String? {
        if (mangaId == null) return null
        val advice = load(context, mangaId).advice.takeLast(limit)
        if (advice.isEmpty()) return null
        return "Советы читателя, соблюдай их: " + advice.joinToString("; ")
    }

    fun render(context: Context, mangaId: Long?): String {
        if (mangaId == null) return ""
        val book = load(context, mangaId)
        if (!book.researched && book.contentType.isBlank()) return ""
        return buildString {
            append("ЗНАНИЕ О КНИГЕ")
            if (book.title.isNotBlank()) append("\nНазвание: ").append(book.title)
            if (book.contentType.isNotBlank()) append("\nТип: ").append(book.contentType)
            if (book.readingOrder.isNotBlank()) append("\nПорядок чтения: ").append(book.readingOrder)
            if (book.site.isNotBlank()) append("\nГде читать: ").append(book.site)
            if (book.summary.isNotBlank()) append("\nО чём: ").append(book.summary)
            if (book.facts.isNotEmpty()) {
                append("\nФакты:")
                book.facts.takeLast(12).forEach { append("\n- ").append(it) }
            }
            if (book.advice.isNotEmpty()) {
                append("\nСоветы читателя (использовать при авточтении):")
                book.advice.takeLast(12).forEach { append("\n- ").append(it) }
            }
            if (book.notes.isNotEmpty()) {
                append("\nЗаметки:")
                book.notes.takeLast(8).forEach { append("\n- ").append(it.text) }
            }
        }
    }
}

package eu.kanade.tachiyomi.data.ai

import android.content.Context
import kotlinx.serialization.Serializable
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import logcat.LogPriority
import mihon.domain.ocr.service.OcrPreferences
import tachiyomi.core.common.util.system.logcat
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get
import java.io.File

/**
 * Продвинутое управление историей AI-чата.
 *
 * Проблемы, которые решает:
 *  - История терялась при пересоздании вкладки / смене процесса (не было persist)
 *  - Тратил до 50к токенов на reasoning двух языков (нет лимита, нет сокращения)
 *  - Не говорил что доступно/невозможно (нет capability report)
 *
 * Решения:
 *  - Файл `workspace/ai_history.json` + StateFlow + лимит из `pref_ai_history_limit` (дефолт 12)
 *  - Токен-бюджет `pref_ai_token_budget` (дефолт 4000) — обрезка истории и max_tokens в запросе
 *  - Availability report перед каждым ходом: сеть, ключи, модели, ранер, локальная LLM
 *  - Сжатие истории: старые сообщения суммируются в краткий «контекст» вместо удаления
 */
object AiHistoryManager {

    @Serializable
    data class Msg(
        val role: String, // user | ai
        val text: String,
        val time: Long = System.currentTimeMillis(),
        val tokens: Int = 0,
        val model: String = "",
        val reasoning: String = "",
        val tools: List<String> = emptyList(),
        val files: List<String> = emptyList(),
        /** Кнопки-варианты [[...]] из ответа модели — повторная отправка текстом. */
        val choices: List<String> = emptyList(),
    )

    private const val FILE = "ai_history.json"
    private val json = Json { ignoreUnknownKeys = true; encodeDefaults = true }

    private fun prefs(): OcrPreferences = Injekt.get()

    fun historyFile(context: Context, mangaId: Long? = null): File {
        val ws = aiWorkspaceDir(context)
        ws.mkdirs()
        return if (mangaId != null) File(ws, "ai_history_${mangaId}.json") else File(ws, FILE)
    }

    private fun aiWorkspaceDir(context: Context): File {
        // Yomikai workspace — /sdcard/Yomikai/AI или внутренние файлы как fallback
        val ext = context.getExternalFilesDir(null)
        val candidate = if (ext != null) File(ext, "../../Yomikai/AI").canonicalFile else File(context.filesDir, "ai_workspace")
        // Fallback если нет разрешения на ext
        return if (candidate.exists() || candidate.mkdirs()) candidate else File(context.filesDir, "ai_workspace")
    }

    fun load(context: Context, mangaId: Long? = null): MutableList<Msg> {
        val f = historyFile(context, mangaId)
        if (!f.exists()) return mutableListOf()
        return try {
            val raw = f.readText()
            val list = json.decodeFromString<List<Msg>>(raw)
            // Обрезаем до лимита при загрузке
            val limit = prefs().aiHistoryLimit().get().coerceIn(4, 100)
            list.takeLast(limit).toMutableList()
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "AiHistoryManager load failed" }
            mutableListOf()
        }
    }

    fun save(context: Context, history: List<Msg>, mangaId: Long? = null) {
        try {
            val limit = prefs().aiHistoryLimit().get().coerceIn(4, 100)
            val toSave = history.takeLast(limit)
            historyFile(context, mangaId).writeText(json.encodeToString(toSave))
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "AiHistoryManager save failed" }
        }
    }

    fun append(context: Context, history: MutableList<Msg>, msg: Msg, mangaId: Long? = null) {
        history.add(msg)
        val limit = prefs().aiHistoryLimit().get().coerceIn(4, 100)
        while (history.size > limit) {
            // Сжимаем: первые 2 сообщения → один summary
            val oldest = history.removeAt(0)
            val second = if (history.isNotEmpty()) history.removeAt(0) else null
            val summary = buildString {
                append("[Сжато: ")
                append(oldest.role).append(": ").append(oldest.text.take(80))
                if (second != null) append(" | ").append(second.role).append(": ").append(second.text.take(80))
                append("]")
            }
            history.add(0, Msg(role = "ai", text = summary, time = System.currentTimeMillis()))
        }
        save(context, history, mangaId)
    }

    /**
     * Оценка токенов грубо: 1 токен ≈ 4 символа (для ru/en). Точнее — после ответа модели.
     */
    fun estimateTokens(text: String): Int = (text.length / 3.5).toInt().coerceAtLeast(1)

    fun totalTokens(history: List<Msg>): Int = history.sumOf { if (it.tokens > 0) it.tokens else estimateTokens(it.text) }

    fun trimToBudget(history: List<Msg>, budget: Int): List<Msg> {
        if (budget <= 0) return history
        var total = totalTokens(history)
        if (total <= budget) return history
        // Убираем старые, оставляя последние дорогие
        val mutable = history.toMutableList()
        while (mutable.size > 4 && total > budget * 0.85) {
            val removed = mutable.removeAt(0)
            total -= if (removed.tokens > 0) removed.tokens else estimateTokens(removed.text)
        }
        return mutable
    }
}

    }
}

