                                }
                                if (!hiddenM.contains("r_voiceicons")) {

                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Text(
                                        if (voiceIconsEnabled) "Значки озвучки: вкл  " else "Значки озвучки: выкл  ",
