                                }
                                if (!hiddenM.contains("r_order")) {

                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    val presetTitle = when (contentPreset) {
                                        "manga" -> "Манга"
                                        "manhwa" -> "Манхва"
                                        "manhua" -> "Маньхуа"
                                        "comic" -> "Комикс"
                                        else -> "Сбаланс."
